/* 2021年11月29日 文教委員会 会議録全文（正式会議録／公式会議録の転載）。scripts/minutes_fulltext.py で生成。 */
window.SHINAGAWA_DB.registerMinutes({"id":"r03-20211129-9","dateIso":"2021-11-29","title":"2021年11月29日 文教委員会","sourceType":"formal","sourceUrl":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5048#one","fetchedAt":"2026-08-14","characters":68331,"voices":[{"i":1,"speaker":"あくつ委員長","text":"○午前１０時００分開会\nただいまより、文教委員会を開会いたします。\n本日は、お手元の審査・調査予定表のとおり、議案審査、請願・陳情審査、報告事項およびその他を予定しております。\nなお、本日は審査の都合上、審査・調査予定表の順番を一部入れ替えて進めてまいります。\nなお、本日の委員会もこれまで同様に、新型コロナウイルス感染症拡大防止のため、委員会室のレイアウトを変更するとともに、理事者の出席も必要最小限とし、適宜入れ替えを行いながら進めてまいります。\nそのため、所管質問については会議の効率的運用の観点から、なるべくご配慮いただきたいと思っております。その上でなお所管質問についてご発言を希望される方は、現時点でお申し出いただきたいと思いますが、いかがでしょうか。"},{"i":2,"speaker":"吉田委員","text":"すみません。これはそもそも所管質問にあたるかどうかも含めて質問したいのですけれども。"},{"i":3,"speaker":"あくつ委員長","text":"それでは、なるべく項目を絞った上で、所管質問の基礎となる一般質問の項目と、質問内容をこの場でお願いしたいと思います。"},{"i":4,"speaker":"吉田委員","text":"１１月２６日の鈴木ひろ子議員のご質問の中で、リニア新幹線に関連するご質問がありました。そのご質問の中に、リニアのルート上の保育園の数を聞いていらしたのですけれども、その保育園の数のご答弁作成にこちらの所管が関わっておられたのかどうか、それを確認させていただきたいのです。保育園の数が、私たちが地図を見た限りでそれでは少なすぎるのではないかと思ったので、所管の保育課と保育支援課が関わっておられたのか、それを伺いたいと思います。"},{"i":5,"speaker":"あくつ委員長","text":"今、お話を伺うと、所管は建設委員会のように聞こえます。確認をしたい内容というのはよく分かりました。ただ、関わっていませんという答えだけを明日聞くのか、それとも関わっていますという答えだけを聞くのかということになると思うのですが、所管は異なると私は思うのですけれども、いかがでしょうか。"},{"i":6,"speaker":"吉田委員","text":"そうですね。だから関わっているかいないかだけでも私としては伺いたい。そうしたら、その後は個別に伺うことになります。"},{"i":7,"speaker":"あくつ委員長","text":"それを委員会でやるべきかどうかということも含めてなのですが。"},{"i":8,"speaker":"吉田委員","text":"それはご判断をお任せいたします。"},{"i":9,"speaker":"あくつ委員長","text":"今、申し上げたように、関わっているのかいないのかということを明日の所管質問で聞くということに、今のお話の内容だとなるのですけれども。"},{"i":10,"speaker":"吉田委員","text":"その具体的なことについては所管が違うというのは承知しているのですけれども、建設委員会のほうの所管で保育園の数などを把握されたのか、それともちゃんとその答弁内容にこちらの所管が関わっていたのか、それだけ確認してからでないと、その先いろいろ質問ができないと思ったので。"},{"i":11,"speaker":"あくつ委員長","text":"お気持ちは分かるのですけれども、どちらかというとそれは建設委員会で聞いていただくことなのかと私は思います。さえぎるとか質問をとめるというのではないのですが、普通に考えてそうなのかと感じたものですから、何かご意見があればお願いします。"},{"i":12,"speaker":"安藤委員","text":"質問の内容自体は、項目自体は所管の委員会に関わる内容の質問なので、吉田委員がこの文教委員会の場でこういう質問をしたいというのであれば、それは尊重されてしかるべきなのではないかと私は思いますけれども、ただ、吉田委員のほうで委ねますと言ってしまうと、何か委員長に任せるのかと思ったので、私は吉田委員がしたいのであれば、所管質問しますということを言うのであれば、それは私としては妥当なのではないかと、しかるべきなのではないかと思います。"},{"i":13,"speaker":"あくつ委員長","text":"ほかの委員はいかがですか。"},{"i":14,"speaker":"松澤委員","text":"個人的な話で言わせていただけると、所管質問ということについて、あまり詳しくお話はできないかもしれないですけれども、私の中のイメージだと、子ども未来部に直接お話をして、それで解決してしまうのかなと個人的には思いました。"},{"i":15,"speaker":"吉田委員","text":"やはりそれだと議事録に残りませんので、それは個別にやればできるのですけれども、要はどう見ても少ないと思って、その後、保育園のことを鈴木ひろ子議員は特に再質問などはされなかったと思いますので、その先は私たちの関心の範囲であり、これは建設委員会マターだし、その後は私たちが個別に所管課とやり取りをすべき問題だとは思いますけれども、ここに関わっていたのかどうかというのは、このリニア新幹線については建設委員会マターですけれども、やはりそれを進めるにあたって影響がある品川区としては、各所管が関わってそれへの対応をしていただきたいという思いがありましたので、ここで伺いたいと思ったということです。"},{"i":16,"speaker":"あくつ委員長","text":"分かりました。先ほどのご意見と一緒だということですね。"},{"i":17,"speaker":"吉田委員","text":"はい、そうです。"},{"i":18,"speaker":"あくつ委員長","text":"ほかの委員はいかがですか。特にないですか。\nでは、私から申し上げます。先ほどのご意見は、やはり吉田委員のおっしゃるとおり、最初のご意見と一緒だと承りました。安藤委員の意見も承りましたが、やはり私の判断とすると、申し訳ないのですけれども、これは建設委員会で聞いていただく。建設委員会の所管が、それは子ども未来部に聞いたのですかという話ですから、それをこの場で聞くというのは、申し訳ないですけれども場がそぐわないのかなと私は考えておりますので、この件は別の形で、委員会ではなくてほかの形で聞いていただくようにお願いさせていただきたいと思います。"},{"i":19,"speaker":"吉田委員","text":"分かりました。"},{"i":20,"speaker":"あくつ委員長","text":"では、よろしいでしょうか。\n以上で本件を終了いたします。\n本日は１名の傍聴申請がございますので、ご案内いたします。\n────────────────────────────────────────────\n１ 議案審査\n(3) 第８６号議案 学校教育職員の給与に関する条例の一部を改正する条例\n(4) 第８７号議案 幼稚園教育職員の給与に関する条例の一部を改正する条例"},{"i":21,"speaker":"あくつ委員長","text":"それでは、予定表１の議案審査を行います。\n予定表では、(1)第６６号議案の審査でございますが、会議の運営上、予定表の順番を入れ替えまして、初めに、(3)第８６号議案、学校教育職員の給与に関する条例の一部を改正する条例および(4)第８７号議案、幼稚園教育職員の給与に関する条例の一部を改正する条例を一括議題に供します。\n本件２議案につきましては関連する内容のため、一括して説明・質疑を行い、その後議案ごとに採決を行いたいと思いますので、よろしくお願いいたします。\n本件につきまして、理事者より一括してご説明願います。"},{"i":22,"speaker":"工藤指導課長","text":"それでは、私のほうから議案審査、第８６号議案、学校教育職員の給与に関する条例の一部を改正する条例、第８７号議案、幼稚園教育職員の給与に関する条例の一部を改正する条例、両案につきまして、説明させていただきます。\n本両条例案につきましては、本年１０月２０日に行われました特別区人事委員会勧告を踏まえ、学校教育職員および幼稚園教育職員の給与に関し、所要の改正を行うものでございます。なお、区職員に関わる改正につきましては、総務委員会での審査となるものでございます。\nでは、続きまして資料１ページをご覧いただければと存じます。改正の内容といたしましては、１、特別給の年間支給月数の改正でございます。こちらにつきましては、特別区人事委員会勧告に基づき、特別給の年間支給月数を、現行の４.６０月から４.４５月に０.１５月引き下げ、この引下げ分につきましては期末手当から差し引くというものでございます。\n続きまして、２ページをご覧いただければと存じます。この０.１５月引下げの対応でございますが、今年度につきましては、３回ある期末手当の支給月のうち、令和４年３月期の期末手当の支給月数を０.１５月引き下げる改正を行うというものでございます。令和４年度以降につきましては３月期の引下げ分を元に戻し、この引下げ分を６月期と１２月期に０.０７５月ずつ均等に割り振る改正を行うというものでございます。こちらの改正につきましては、学校教育職員および幼稚園教育職員に共通するものでございます。\n次に、２ページ目の２、両条例の施行日でございますが、３月期の期末手当の支給月数に係る改正につきましては公布の日から施行することとし、令和３年１２月１０日を予定しております。令和４年度以降の期末手当支給月数に係る改正は、令和４年４月１日より施行することといたします。\nなお、月例給の改正につきましては、学校教育職員および幼稚園教育職員ともに今年度はございません。"},{"i":23,"speaker":"あくつ委員長","text":"説明が終わりました。\n本件に関しましてご質疑等がございましたら、ご発言願います。"},{"i":24,"speaker":"安藤委員","text":"まず、労使が妥結したのか、それはいつかということをお伺いしたいのと、２点目は、今回の減額で、実際に平均年間給与としてはどれぐらい下がるのかというのを、それぞれ第８６号議案と第８７号議案で分かれば教えてください。\n３点目は、今回引下げということなのですけれども、どちらも子どもの育ちに直接関わる仕事だけに、モチベーションへの影響が少し心配でありまして、教師の働き方はずっと問題になっていますけれども、ブラックな労働環境に大きな影響を与えるのは裁量権がないという点と、長時間の労働が続くと。この２点の要素が大きいと言われているのですが、残念ながら教員の仕事というのはどちらも当てはまってしまっているというのが今の現状だと思うのです。その上給料まで下がってしまうと、モチベーションが下がってしまうのではないか、それはよくないのではないかと思うのですけれども、そこら辺の影響について、区教委の認識を伺いたいと思います。"},{"i":25,"speaker":"工藤指導課長","text":"３点頂きました。\nまず、交渉の妥結でございますが、私どもの情報としては、１１月１８日木曜日深夜に妥結されたと報告を聞いているところでございます。\nまた、この改正によるいわゆる影響というところでご質問いただきましたけれども、こちらにつきましては、いわゆる公務員の給与と民間の格差をなくすという目的に沿って行われたものでございますので、これは学校教育職員および幼稚園教育職員も同様にということでございます。また、その中でそれぞれ働き方改革については各学校、あるいは幼稚園につきましても今取り組んでいるところでございますので、そういった意味で、教育にかけるモチベーションが下がるとは考えてございませんが、引き続き働き方改革は進めなければいけないという認識でございます。\n実額につきましては、勧告の際に申し上げたのと同額でございまして、およそマイナス５万９,０００円。またこれを区固有教員である学校教育職員と幼稚園教育職員で合わせますと、本年の実質でいきますとほぼ同じなのですが、大体平均すると５万７,６００円という金額でございます。"},{"i":26,"speaker":"安藤委員","text":"額で言うとやはり決して少なくない額なのかなと思ってしまうわけです。確かにモチベーションの問題というのは、給料という面も一側面ですけれども、特に学校現場の場合はあまりに長時間ということと、長時間の上に教員が創意工夫を持って自分たちでする裁量権がないということなのです。その２つが大きな問題だと思っていますので、その両面から、先ほど働き方改革を進めていきますというご答弁でしたけれども、ぜひそちらは強力に進めていただきたいと思います。"},{"i":27,"speaker":"あくつ委員長","text":"ほかにございますでしょうか。よろしいでしょうか。\nほかにご発言がないようですので、これで質疑を終了いたします。\n採決に入ります前に、まず第８６号議案、学校教育職員の給与に関する条例の一部を改正する条例につきまして、各会派の態度を確認いたします。\nそれでは、品川区議会自民党からお願いいたします。"},{"i":28,"speaker":"松澤委員","text":"賛成です。"},{"i":29,"speaker":"つる委員","text":"賛成です。"},{"i":30,"speaker":"安藤委員","text":"人事差別スパイラルになるという点と、教育の質の向上から望ましくはありませんが、労使が妥結しているということ、それと区採用教員と都採用の教員での待遇格差が出るということもあまり望ましくないということで、反対するものではありません。賛成です。"},{"i":31,"speaker":"吉田委員","text":"生活者ネットワークとしても、教員の働き方とか幼稚園教諭の働き方などを考えると、このマイナスの額は平均ですけれどもかなり大きいと思っております。ただ、そもそもの官民格差の是正ということと、それから人事委員会勧告に基づいて労使が妥結しているということを尊重いたしまして、賛成をいたします。"},{"i":32,"speaker":"松本委員","text":"賛成です。"},{"i":33,"speaker":"あくつ委員長","text":"それでは、これより第８６号議案、学校教育職員の給与に関する条例の一部を改正する条例について、採決いたします。\nお諮りいたします。本案は原案のとおり決定することにご異議ありませんか。\n〔「異議なし」と呼ぶ者あり〕"},{"i":34,"speaker":"あくつ委員長","text":"ご異議なしと認めます。よって、本案は全会一致で原案のとおり可決決定いたしました。\n次に、第８７号議案、幼稚園教育職員の給与に関する条例の一部を改正する条例につきまして、各会派の態度を確認いたします。\nそれでは、品川区議会自民党からお願いいたします。"},{"i":35,"speaker":"松澤委員","text":"賛成です。"},{"i":36,"speaker":"つる委員","text":"賛成です。"},{"i":37,"speaker":"安藤委員","text":"第８６号議案とほぼ同様の理由から、賛成いたします。"},{"i":38,"speaker":"吉田委員","text":"私も先ほどと同じ理由で、賛成をいたします。"},{"i":39,"speaker":"松本委員","text":"賛成です。"},{"i":40,"speaker":"あくつ委員長","text":"それでは、これより第８７号議案、幼稚園教育職員の給与に関する条例の一部を改正する条例について、採決いたします。\nお諮りいたします。本案は原案のとおり決定することにご異議ありませんか。\n〔「異議なし」と呼ぶ者あり〕"},{"i":41,"speaker":"あくつ委員長","text":"ご異議なしと認めます。よって、本案は全会一致で原案のとおり可決決定いたしました。\n以上で、本件を終了し、議案審査は一旦これまでといたします。\n────────────────────────────────────────────\n２ 請願・陳情審査\n(2) 令和３年請願第１２号 品川区天然記念物第１５号戸越八幡神社ケンポナシ保存に関する請願"},{"i":42,"speaker":"あくつ委員長","text":"次に、予定表２の請願・陳情審査を行います。\n予定表では、(1)令和３年請願第１１号の審査でございますが、会議の運営上、予定表の順番を入れ替えまして、(2)および(4)の審査を先に行います。\nまず初めに、(2)令和３年請願第１２号、品川区天然記念物第１５号戸越八幡神社ケンポナシ保存に関する請願を議題に供します。\n本件は初めての審査でありますので、書記に朗読させます。\n〔書記朗読〕"},{"i":43,"speaker":"あくつ委員長","text":"朗読が終わりました。\nそれでは、本件に関しまして、理事者よりご説明願います。"},{"i":44,"speaker":"有馬庶務課長","text":"それでは、私から本件についてご説明いたします。\nまず、本請願は、戸越八幡神社に生息しています区指定天然記念物であるケンポナシの保存につきまして、区として適切な措置を取るようにとの申し出でございます。\n本ケンポナシは隣地との境界際にありまして、枝葉や根の一部は隣地に張り出しています。このたび、この隣地に集合住宅の計画があり、ここに記載の理由のとおり、根の切除等によるケンポナシへの影響を心配しての請願ということで理解をしております。\nそこで、まずこの本件天然記念物ですが、品川区の文化財保護条例に基づき、所有者である戸越八幡神社にまずは管理義務があるということでございます。同時に、同条例では区の責務としては、区は保存と活用が適切に行われるように努めることとされており、また、区民についてもその保存活用のため必要な措置を講じ、文化的向上に貢献するというこの条例の目的を達成するために区がいろいろ行う措置について、誠実に協力してくださいというようなことがこの文化財保護条例では言われています。\n併せて、教育委員会は関係者の所有権その他の財産権を尊重し、文化財の保護と他の公益との調整に留意しなければならないとも規定されていると。こういったところが文化財保護条例の紀要にうたわれているところでございます。\n本件についての経緯でございますが、昨年６月に建設事業者より区のほうに相談を受けております。その際、根を切ることとか、アパート集合住宅を建てることによって、上のほうの枝葉を一部刈ることになる可能性もあるということで、それの影響によって天然記念物の樹勢に少し影響がある懸念があるということになりますと、これは現状変更にあたる可能性が強いですよということで、その場合は施行規則に基づき、所有者の承諾が必要になりますということ。それから、樹木医等の客観的な判断によって、この建築計画を計画どおり行っても、ケンポナシの文化的価値を損なわない計画とすることが必要となりますということを伝えてあります。\nその後、神社側からも何度となく相談を受けているところです。事業者側は樹木医診断を行うとともに、計画上、セットバックを含めた設計変更を行うなど、神社側にもその相談を持ちかけているようですし、神社側もまた別の樹木医が診断を行っているというような状況でございます。双方の診断結果に若干の相違も見られまして、現在は話し合いの協議は進めており、事業者側もさらなる設計変更をもう一度考えてみようかということになっているということでございます。\n本件につきましては、区として何ができるかということですが、今のところ双方でも話し合いが進んでおり、何とかその話し合いの中で決着ができればと思っております。今しばらくは話し合いの推移を見守るとともに、さっき述べたように区は適切に助言・アドバイスをして、保存と活用が適切に行われるように努めてまいりたいと考えております。"},{"i":45,"speaker":"あくつ委員長","text":"説明が終わりました。\nこれより質疑を行います。ご質疑等がございましたら、ご発言願います。"},{"i":46,"speaker":"安藤委員","text":"様々なご説明があったのですけれども、教育委員会としては、この当該樹木の文化的価値についてどのように認識をされているのか伺いたいというのが１点です。\nそれと、文化財保護条例の紹介がありました。第３条第２項の紹介がありましたけれども、その区民というのにこのマンション事業者はあたるのかということを確認させていただきたいのと、あと、同じ第３条の第３項に、文化財の所有者その他の関係者は、文化財が貴重な公共的財産であることを自覚し、これを公共のために大切に保存するとともに云々、努めなければならないと書いてあるのですが、このその他の関係者にはあたるのかどうか、そこら辺をお伺いしたいと思います。"},{"i":47,"speaker":"有馬庶務課長","text":"まず、本件ケンポナシの文化的価値でございますけれども、今、区の中では天然記念物が１９件ありますけれども、そのうちケンポナシとしては１件でございまして、樹齢もこれは推測にはなりますけれども、それも含め、昭和５３年ぐらいに調査し、一定程度価値があると認めた上での指定となっており、現在でも天然記念物としての価値があると考えております。\nそれから、第３条の関係です。区民はというところですが、事業者については直接この区民というよりは、第４項のところで言っています関係者と捉えるほうがよろしいかと、考えているところでございます。"},{"i":48,"speaker":"安藤委員","text":"やはりその他の関係者ということで、ぜひこの文化財の貴重な公共的価値を知っていただいて、保存と公開と活用に努めていただくために努力していただきたいと思いますし、引き続き所有者の神社にしっかりとお話を伺いながら、相談も受けながら、区教委としてできることを、ぜひ条例にのっとって進めていただきたいと思います。"},{"i":49,"speaker":"松澤委員","text":"戸越八幡神社は私の氏神という部分ではすぐ近くなので、何回も見に行っております。それで、いろいろお調べしましたけれども、東京全体で見ても、このケンポナシというのはもしかしたら１本しかないかもしれないぐらい、大変貴重だということは聞いております。\nそういった中で日本樹木遺産委員会というのがありまして、そこでもこの戸越のケンポナシが日本樹木遺産の第一樹木に認定されるなど、大変貴重なものであるのかなというのは、品川区の本当に大きな財産だと思っております。\nそこで、ある程度品川区でいろいろ管理等をやってもらいたいということにおいても、移動できたらいいと思うのですけれども、レッカーが入らなかったりして移動もなかなか難しそうです。いろいろな課題がある中、こういう天然記念物というものをどのように品川区としては守っていくのかといったところを少しお話しください。"},{"i":50,"speaker":"有馬庶務課長","text":"まず、天然記念物ですけれども、あくまでも管理は所有者にあるということでして、日常的な管理、場合によっては剪定ですとかいろいろな部分があると思いますけれども、そういったものには保護奨励金というものをお出ししたりしておりますので、そういったところでの管理もお願いしているところでございます。\nそれから、どうやって守っていくのかというところですけれども、今回のことにつきましては、これはもう生き物ですので、やはりいつかは枯れるということはあるかもしれませんけれども、できるだけ悪い影響がないようにというようなところで、今回についてもこの建築業者については、根をどの程度切ったら影響があるのか、できるだけ根を切らない方向で設計をするですとか、そういったところに配慮していこうというところで対応してもらっていますので、そのような工夫をしながら、地上のほうは枝葉もありますので、そこもできるだけ影響がないようにですとか、そういったところはいろいろ検討してもらって、計画を立ててもらっているという状況でございます。"},{"i":51,"speaker":"松本委員","text":"先ほど現状変更という話が出たかと思いますけれども、これが今のところ現状変更にあたりそうなのかというところと、条例上は現状変更にあたると、教育委員会の許可が第１４条第１項で出てくるかと思うのですけれども、この辺りの対応は今どうなっているのか、お願いいたします。"},{"i":52,"speaker":"有馬庶務課長","text":"今回のこういう例は、現状変更まで至らない軽微なものは必要ないというふうにも併せて書いてあると思いますけれども、例えばちょっと枝が伸びてきました、少し剪定させてくださいというようなことでお隣と話し合いがつけば、それはそれで構いませんということですね。\nこのケンポナシもこれから樹勢がどんどん大きくなる、そこの部分まで保証しろというと、それはまた少し話が違ってくるかと。いわゆる現状ですから、現状が維持できればいいですよというところまでしか言っておりませんので、そういった意味で、今回根を切ったり枝を切ったりすることによって、現状の樹勢が衰えてくる可能性がある場合は、その計画は少し見直してくださいと。できるだけ今の樹勢が保たれるような形での計画にしてくださいと。それは、切るのは事業者ですけれども、その変更を加えるということは所有者に承諾を取ってくださいというような形での変更届という形になります。所有者の承諾を取って、事業者が変更届を出すということになります。\nそれから、それを受けたら、区のほうは最終的には教育委員会にかけて、こういう形で変更します。これは例えば以前あったのは、台風で倒木してしまって、もう樹勢も駄目だといった時には廃止しますといった時も、これは文化財保護審議会にかけて、そこから意見をもらって、最終的に教育委員会にかけて決議した。そのような流れになっています。"},{"i":53,"speaker":"松本委員","text":"ありがとうございます。多分一つの大きなところは、今軽微に当たるかどうかというところで、これは根を切るとかとなると、ここが多分解釈だと思うのですけれども、そこの点で軽微でないとなると、ひとつ許可という段階が上がっていくのだと思いますので、事業者は当然知っているとは思うのですけれども、そこの部分でこれを条例の中でどこまでできるのかというところを考えると、これは許可の対象になり得るというところについては、これは情報提供というところで可能だと思うので、そこをやはり守っていくというのが大事だと思いますので、ぜひそこのところを条例上できる範囲内で解釈を頑張っていただいて、やっていただきたいと思います。以上、要望です。"},{"i":54,"speaker":"つる委員","text":"今、隣接している施工主のほうが、建築上のいろいろな工夫等をやっていただいているという現状かと思いますし、またケンポナシとしては、今各委員からあったとおり、今後もずっとそこに生育できる環境をしっかり確保できるかというところを、今、現場では専門家同士で一生懸命やり取りをしていただいているというところで、その技術的なところについては専門的ないろいろなやり方があるのでしょうし、別の話で土木関係でいくと、よく桜の木が根上がりしてしまって、その課題をいろいろなところでいろいろな技術を活用して、今かむろ坂の桜とか、目黒川沿いの桜とか、根上がりしないようなやり方のものになっています。\n今後ずっと自生するということは、その隣接している根っこの部分で、どういう形で根が地面で張っていくかというのは分からないわけだけれども、それをあまり隣接しているほうに行かないような工夫、それがまた木の生育上影響がないやり方という土木的な技術というのは、施工業者を含めてやっていただきたい。これは別の次元の話かもしれませんが、ただそういったところの調整を、区の教育委員会としてやられるというところだと思いますので、今現在も、これまでもやっていただいているというのは最初のご説明の中でも理解しました。\nただ一方で今後というところで、今回の請願の採決というのはこの後されるわけですが、やはり具体的に、先ほど安藤委員からあったマンションの事業者というのはマンションを売るほうだと思うんですけれども、そこに今度新しい住民が住まわれて、まさにその方々が区民となられて、管理組合が持つようなマンションかどうかわかりませんが、いろいろな意思決定だとか、またいろいろな物に対する考え方とかが出てくるときに、当然区民というところで、条例のそういう責務の中に入ってくると思うのです。\nただ、それがまさに天然記念物のものであるのですよということが、新たに入ってくる、同じ区民の方か、区外の方かも分かりませんけれども、そこに住むにあたって、日常の中に目の前にそれがそういうふうにあるということが当然分かった上でご購入されたり、賃貸なのか分譲なのか存じ上げませんけれども、そういうふうになっているといった時に、そういった声がやはり事前にしっかりと理解いただけるような形の調整を取っていただくということも、一方で必要なのかなと思うわけです。\n新しい住民の方が、このケンポナシが品川区天然記念物なのだということが分かるような工夫というのは必要なのかなと思いますが、この辺りについては、今この条例上で区として積極的にやることはないのかもしれませんが、どういうところまでできるものなのか教えてください。"},{"i":55,"speaker":"有馬庶務課長","text":"まずは、今後の生育への影響というところでは、やはり専門家の意見をしっかり聞くということと、それからやはり双方話し合いの中で納得してもらうのが一番かと思っていますので、その辺のところは今後我々も中に入って、お互いどこまでいけば納得できますかというところの調整に入っていきたいと思います。\nそれから、住民の方への周知というところなのですけれども、ここは我々もいろいろ調べてみたのですが、非常に難しいところがありまして、まず今回の建築確認はもう下りているのです。その時に、重要事項の説明の中に入るのかというところも調べたのですけれども、史跡であればそういったところの要件に当たるのですけれども、区の天然記念物のレベルですと、そこまでの責務はないようなのです。しかも、建築確認の時には民間の事業者も受け付けたりしますので、どこまでそれが周知できるかというところは、ひとつ課題かなと思っています。\n今後もアパートを借りるときに、その集合住宅を建てた方がどこの不動産屋に募集依頼をかけるのかというところもあると思うので、そこの隣に天然記念物がありますよというのをどのように周知をすれば、最初の契約のときに分かるのかというところは一つの課題かなとは思うのです。そこは必ず周知しなければいけない重要事項なのかどうかというところは、貸主に対してはそこまで法的には義務はなさそうですけれども、一つの重要な要件としては、借りる時の項目として、チェック欄として天然記念物がありますよみたいなところは、建築の際にはあるようですので、それがどこまでできるかということは課題かなという感じです。"},{"i":56,"speaker":"つる委員","text":"さっきの松本委員の質疑の中で、現段階での対応というところでの現状の捉え方だったのですが、そうすると今後は、やはり新しく住まわれる方、そのケンポナシに対する思いがどのように捉えられるかによっていろいろなご意見が、今後所有者である戸越八幡神社に対していろいろあるのかなというところとか、また天然記念物になっている以上、それは区がそのように指定したとなれば、皆さんから区にそういう話が来ると思うのです。\nそういった時に、やはりいいものですし、先ほど松澤委員のご指摘の中では都内で一本とかという貴重なものだというようなご理解がより進むような工夫というのは、一方で考えるとすれば戸越八幡神社のほうでいろいろな啓発・周知をしていただくようなものを、今までもやられている区がつけた看板みたいなものがありますけれども、もう少し理解いただけるようなことをやっていけば、新しく入ってきた段階で、逆に言うとそういうものが隣接しているところに住めるというプラスの付加価値というようなことにつながる工夫も、何社になるか分からないけれども、いろいろそれぞれが知恵を出し合ってできるような形が、この請願を頂いている中では一番いいのかなと。\n現状はそういう対応と、今後というところでやれることをいろいろ知恵を出し合って、ぜひやっていただきたい。今現状の写真を見る限りでは空間になっていて、そこにどういう形で建屋が建っていくのかというのが、その辺のつくりによっていろいろな声がまた今後出てくる。枝が出てくるから切ってくれとか、枯れ葉がどうだとか、いろいろそういう細かい話もまた今後出てくると思うのです。そういうトラブルが今後ないようないい形で進められればと思います。"},{"i":57,"speaker":"吉田委員","text":"ぜひこれが残るような形で、話し合いが進むといいと思います。つる委員がおっしゃるように、今後の住居者のところまで心配しなくてはならないということは、これが残るということですので、まずは残す方向で話し合いが進んでほしいと思います。\n先ほどの質疑の中で、その変更が軽微でなければ、文化財保護条例の中の第１４条のところで、品川区教育委員会としての許可が必要になってくる。先ほどご説明の中では、建設事業者のほうが相談をしている専門の樹木医と、それから所有者側の樹木医の間で、多少の意見のそごがあるかなということで、それはもう専門家の中でというのは当然だと思うのです。\n今後、例えばもし品川区の許可の問題になってきた時に、品川区としてもまた別の専門家、樹木医の意見を聞くとか、そういうところまで考えておられるのかというのをまず伺いたいと思います。"},{"i":58,"speaker":"有馬庶務課長","text":"まずは、これは所有者の神社があって、隣に事業者がアパートを建てるというところでの話し合いですので、お互いが納得してくれればいいということが大原則であるので、すぐに区が入っていって、そこでこういうやり方でという仲介ということでは制度的にはないのです。あくまでも双方が納得の上という形になりますので、それぞれの樹木医の話が違うところがありますけれども、そこで折り合いをうまくつけてもらうようなやり方を模索してもらうということで今考えていますので、区が直接ではこうやりましょうという提案をするということは、今の段階では考えておりません。"},{"i":59,"speaker":"吉田委員","text":"ごめんなさい、質問の仕方がまずかったです。基本は当事者の方たちの判断というので当然だと思います。そこで今、それぞれの樹木医の意見が分かれていたりして、将来的にこれが例えば軽微な変更ではなくて、区の許可が必要なレベルまでの変更になった時には区としても、決着がつけば問題はないです。私もそれを区としてどうこう意見を出すべきということは聞いていないのですけれども、将来的にはもしもそういう条件が必要になった時には、区としては教育委員会としての判断だけではなくて、そこに別の立場の樹木医の意見とかも聞く予定はあるのかということを伺います。"},{"i":60,"speaker":"有馬庶務課長","text":"まず、これは軽微な変更ではないので、今、吉田委員が言った一歩先の届け出が必要な措置として区は動いているということですので、今所有者がそれでいいですよという承諾を取り、その承諾書を持って事業者が変更届を出すというその手続きです。軽微な変更だったら手続きは要りませんという話なのですけれども、いわゆる天然記念物の変更届を出してくださいというぐらいの影響がある可能性がある計画ですよねということで、今話し合いを進めているという形ですので、一歩先の届を出してもらう前提で動いていますけれども、その中でも当区として樹木診断を直接やるということは、今のところはまだその考えはないです。"},{"i":61,"speaker":"吉田委員","text":"分かりました。そういうことが必要になった時にはぜひそうしていただきたいというのもあって、伺いました。\n生活者ネットワークの中で、私が議員になる前に、これは天然記念物ではないし、ケンポナシでもなく、それでも樹齢は何百年のイチョウの木が立っているお寺の隣にマンションが建つということで、近隣の方たちの間でいろいろ議論が進んで、それで学習会とかも開きながら近隣の方たちと調整をして、結果、今無事にそのイチョウは元のところに残っているのです。もちろんイチョウでメスなのでギンナンもなって、マンションの方にとってはもしかして迷惑なこともあるかもしれないけれども、やはりまちづくりの在り方によってはそれはきちんと継続していくのだなと、そのイチョウを見るたびに、まだしっかりと元気でいるなということで私としても喜んでいます。\nこれは、本当に区としての天然記念物ですし、ぜひ皆さんで残す方向で話し合いが進むことを望んでいますし、ぜひ区としてのその辺についてはお力を出していただきたいと願っております。これは意見です。"},{"i":62,"speaker":"あくつ委員長","text":"ほかにございますでしょうか。\nほかにご発言がないようですので、これで質疑を終了いたします。\nそれではまず、令和３年請願第１２号の取扱いについてご意見を伺いたいと思います。\n継続にする、あるいは結論を出す、どちらがご発言願います。また結論を出すのであれば、その結論についてもご発言ください。\nそれでは、品川区議会自民党からお願いいたします。"},{"i":63,"speaker":"松澤委員","text":"本日結論を出すで、採択でお願いします。\n先ほどもいろいろお聞きしましたけれども、文化財保護条例に基づきましてしっかりと引き続き管理をしていただきたいと思います。"},{"i":64,"speaker":"つる委員","text":"本日結論を出すで、採択です。\n先ほどの質疑の中でもお伝えさせていただきましたが、まさに今後についてしっかりと区として調整、また所有者、そして隣接の事業者および後の区民となられる方々の調整をしっかりとお願いしたいと思います。"},{"i":65,"speaker":"安藤委員","text":"本日結論を出すで、採択です。\n区民がはぐくんできた大切な地域文化を守るために、区としても条例に基づいて最大限努力をしていただきたいと思います。"},{"i":66,"speaker":"吉田委員","text":"本日結論を出すで、採択を主張いたします。\n先ほども言いましたけれども、これは区の天然記念物に指定されていますけれども、品川区にはほかにもいろいろ貴重な樹木があります。そういう時にはぜひ区としてもそれは残す方向で力を尽くしていただきたいですし、品川区議会としてもぜひそれを後押しする方向で、この請願を採択したいと思います。"},{"i":67,"speaker":"松本委員","text":"本日結論を出すで、採択でお願いします。"},{"i":68,"speaker":"あくつ委員長","text":"それでは、本請願につきましては、結論を出すとのご意見でまとまったようでございますので、そのような取扱いでよろしいでしょうか。\n〔「異議なし」と呼ぶ者あり〕"},{"i":69,"speaker":"あくつ委員長","text":"それでは、本件は結論を出すことに決定いたしました。\n先ほどそれぞれの方のご意見を伺いましたので、本請願につきましては、簡易採決により採決を行います。\nそれでは、令和３年請願第１２号、品川区天然記念物第１５号戸越八幡神社ケンポナシ保存に関する請願についてお諮りいたします。\n本件を採択とすることにご異議ありませんか。\n〔「異議なし」と呼ぶ者あり〕"},{"i":70,"speaker":"あくつ委員長","text":"ご異議なしと認めます。\nよって本件は採択と決定いたしました。\n以上で、本件を終了いたします。\n────────────────────────────────────────────\n(4) 令和３年陳情第５８号 品川区立学校図書館の充実に関する陳情"},{"i":71,"speaker":"あくつ委員長","text":"次に、(4)令和３年陳情第５８号、品川区立学校図書館の充実に関する陳情を議題に供します。\n本陳情は初めての審査でありますので、書記に朗読させます。\n〔書記朗読〕"},{"i":72,"speaker":"あくつ委員長","text":"朗読が終わりました。\nそれでは、本件に関しまして、理事者よりご説明願います。"},{"i":73,"speaker":"吉田品川図書館長","text":"それでは私から、品川区立学校図書館の充実に関する陳情につきまして、学校図書館運営支援業務のご説明をいたします。\n学校図書館は児童・生徒の健全な教養を育成することを目的として、学校図書館法で学校に設けることを義務づけられた施設です。校長が学校図書館長となり、児童・生徒・教員の利用に供するため、資料を収集し、その整理を行っています。区では学校図書館支援のため、学校図書館運営支援スタッフを配置する事業を行い、平成２５年から全校に週１５時間、年間７３５時間実施し、学校図書館の貸出し、返却等、学校図書館現場で支援を行っているところです。また、月ごとに副校長、図書館担当教諭、受託事業者の責任者および運営スタッフによる作業企画会議で運営内容を定めて活動しております。この会議には受託事業者の責任者が同席し、学校長の業務指示、依頼を調整しているところです。\n今回の陳情における学校図書館運営支援スタッフ配置時間の要望についてですが、現在区では各学校の自主性・主体性に基づき、学校図書館事業の実施のため、学校図書館運営支援スタッフ、学校図書館ボランティア等が協力し、学校とともに運営の充実にあたっています。そのため、地域に開かれた学校として、様々な人材が学校図書館運営に関わっているところです。今後の学校図書館の充実に関しましては、学校と連携しながら進めてまいります。"},{"i":74,"speaker":"あくつ委員長","text":"説明が終わりました。\nこれより質疑を行います。ご質疑等がございましたら、ご発言願います。"},{"i":75,"speaker":"安藤委員","text":"まず区教委として、新学習指導要領でもうたわれるようになりました、学校図書館の計画的な活用、授業での活用の重要性についてどういう認識をお持ちなのか伺いたいと思います。それにあたって、学校図書館運営支援スタッフの働きをどう位置づけていくのか、伺いたいと思います。"},{"i":76,"speaker":"吉田品川図書館長","text":"２点ご質問いただいたかと思います。\n学校図書館における授業の活用、重要性につきましては、現在も学校図書館におきまして、読み聞かせ、それからブックトーク、そういう形のほかにもリファレンス等で学校の授業におけるサポートおよび協力をしているところでございます。\nそれから、働きについてどう考えているかというところですけれども、学校図書館の重要性につきましては当然認識しているところでございますので、今後も学校の中において、しっかりサポートしていける体制を整えていこうと考えているところでございます。"},{"i":77,"speaker":"安藤委員","text":"重要性があるということでサポートしていきたいということなのですが、品川区では学校司書ではなくて、学校図書館運営支援スタッフという名称なのですけれども、改めてなぜそういう名前にしているのかという理由を伺いたいというのが１点です。\nそれと、支援スタッフなのですけれども、司書資格が現状必須になっているかどうか。どちらに業務委託をしているのか。実際司書資格を持っている方の割合はどのぐらいなのか、伺いたいと思います。\nあと、一遍にすみません、授業の支援の上でも、タブレット端末が配布されておりますけれども、当然図書館での活動の中でもタブレットやネット等での調査など、資料検索とかというのが当然大事になってくると思うのですが、今現状では、この運営支援スタッフに対してのネット環境はどのようになっているかというのも併せてお伺いします。"},{"i":78,"speaker":"吉田品川図書館長","text":"学校司書と言わずに運営支援スタッフと呼んでいるところですけれども、内容的には学校司書等と同じでございます。\nそれから、司書資格の有無についてですけれども、委託の際に司書資格については、司書資格のある者を採用するようお願いしているところです。実際は約８割以上を越えた者が支援スタッフの中では司書資格を持っております。\nそれから、委託先につきましては、図書館流通センター、それから特定非営利活動法人ウーヴ、それからナカバヤシ株式会社、こちらの３社で、委託関係としましては学校を５つの区分で分けておりまして、そこを３社で委託受注しているところでございます。\nそれから支援スタッフのネット環境でございますけれども、支援スタッフにつきましては特にインターネット等に抜けられる仕組みを図書館内で持っているということは特にございません。その関係で、必要に応じて学校の教材系等から、インターネット等を検索していただくような形になっているところでございます。"},{"i":79,"speaker":"安藤委員","text":"ネットのところは、支援スタッフがその図書館の中で児童・生徒の支援ができるためには、やはり専用端末を配ったりとか、あるいは図書館の中に検索できる端末を入れるとか、そこら辺はぜひ充実していただきたいと思います。そのようになっているのか伺いたいと思います。\nあと、現在各学校に一律に週２.５日、１５時間配置するという計画の根拠、基準の考え方、なぜこのようにしているのかを伺いたいと思いますし、これはずっと変わっていないのか伺いたいと思います。\nそれと併せて予算なのですけれども、現在の支援スタッフの配置に関わっているこの委託費の予算というのは年間幾らになって、その財源構成はどこかから補助金が出ているのかとか、その辺についても伺いたいと思います。"},{"i":80,"speaker":"吉田品川図書館長","text":"支援スタッフの端末の環境につきましては、実際は特に学校図書館内で何か検索できるという状況は整っていないところでございます。こちらは普段、図書館内で自由にインターネットができるという状況を、安全性のために整えていないという面もございまして、現在の状況となっているところです。\nそれから、一律に２.５日にしている根拠ですけれども、これはしばらく前から品川区の場合は２.５日のまま来ているところでございますけれども、これは各学校の自主性に合わせながらも、学校と学校司書、それからボランティアの人たちが協力しながら進めていくのにあたりまして、現在はこの２.５日を基準にやっております。\nそれから予算につきましては、委託費が全校につきまして年間約９,９００万円ほどとなっております。それから財源につきましては、一般財源が全てでございます。"},{"i":81,"speaker":"安藤委員","text":"ネットのところは、生徒一人ひとりに端末を配っているわけですから、やはり図書事業の充実にあたっては、セキュリティに最大限配慮するのは当然ですけれども、しっかり支援ができるように今後しっかりとネット環境を整えていただきたいと思います。\nそれと、１５時間、週に２.５日ということの理由が分かりづらいご答弁だったのですけれども、一律２.５日、１５時間ということですと、やはり学校の中でも学年によって、図書の授業で図書館に行って授業をしますよという時に、支援員がいる学年といない学年とかが出てしまいますし、学校間ではこの陳情にありますように、大きなところというのはクラスが多いわけですから、ほとんど配置されなくなってしまう。図書の授業にほとんど支援員がいない学校と、そこそこいる学校というように、それぞれやはり学校図書館利用の上での格差というのはどうしても出てきてしまうと思うのです。やはり実態に合っていないと思うのですけれども、そこら辺の利用格差について問題がないという立場なのか、それをお伺いしたいです。\nそれと、もう一度今の基準、時間数にしている政策根拠というのは、なぜこういう少ない時間にしているのかというのをもう一度分かるようにお願いしたいと思います。"},{"i":82,"speaker":"吉田品川図書館長","text":"学校の利用の格差というところでございますけれども、学校によっても学校司書との連携の仕方というのは異なります。それぞれ読み聞かせが多い学校があれば、リファレンスが多い学校があったりとか、それぞれ学校の独自性とかによっても異なる部分があるので、ちょっとそこの一律の比較はなかなか難しいと思います。\nそれと、今の時間数ですけれども、２.５日の週１５時間のところでございますけれども、今回のこの学校図書館運営支援委託につきましては、平成３０年度から５年間ということで、総合評価方式で進めております。その関係で、各校５年間につきましては一定程度同じ状況で進めていかなければならないというところもございますので、以前の答弁で５年、１０年というところでまた見直していくというお話もあったと思いますけれども、今後必要に応じて考えていく部分だと考えております。"},{"i":83,"speaker":"安藤委員","text":"やはり必要に応じてということですが、もう絶対必要だと思うのです。他区などは陳情にもありますように、今の新時代に必要な、もう博物館に入っているような一斉の授業ではなくて、探求と共同の学びというのをやっているわけです。そういうことを目指して動いているわけで、そういう対話をするためには、やはり学校図書館の充実というのは必要だし、そこに人の充実がなければ、それは絵に描いた餅になると思いますので、一定期間後には見直すとありますけれども、必ずこれは充実の方向で見直していただきたいと思いますし、そういう方向を議会としても後押しすべきだと思います。\n格差の問題については、実際いろいろやり方があると言いますけれども、図書の授業になったら実際クラスごとに先生と一緒に図書館に赴いて、いろいろ調べ学習をしたりするわけではないですか。だから実際に大きな学校と小さな学校ではクラス数が全然違うわけですから、どのような大きな学校であっても１５時間となると、当然この少ない授業の中でどうしようかということで、ほとんどその学校としては支援スタッフがいる中での図書の授業は受けられないということになるわけですから、これは私は解消する必要があると思います。区教委としてはこの学級数が多いところでも、もう５年とか１０年とか言っていないで、少しでも増やしていくという姿勢を私は持つべきだと思うのですけれども、何がネックなのでしょうか。お金なのでしょうか。そこら辺を伺いたいと思います。"},{"i":84,"speaker":"吉田品川図書館長","text":"学級数が多いところにどう対応していくかについて、現状何がネックになっているかというところでございますけれども、いろいろな面があると思います。ただ、学校図書館の運営につきましては、学校が主体的に運営するところの支援という立場がございます。それと学級数、あとは金額的にもいきなりこれを増やすというのは、約１億円でございますが、金額的にも大きいところではございますので、一律にどれが原因ということもありませんけれども、今後いろいろな意味で検討を図っていかなければならないところだと認識しているところでございます。"},{"i":85,"speaker":"矢部教育総合支援センター長","text":"少し補足をさせていただきます。学校現場は様々なお子さんとかニーズとか単元、授業もありますので、毎日図書室に行くかといったらそうでない日もありますし、ここで働いていらっしゃる運営の方についても、１日整理の時間になることもあります。ですから、日々違うということはご理解いただきたいと考えます。\nまた、朝は今も図書館長からもありましたけれども、読み聞かせで各地域からボランティアで来ていただいて、低学年から高学年に行く場合もあります。そのようなことでも協力いただいておりますし、図書の時間はスタッフはもとより、担任からも低学年などは読み聞かせをしております。調べ学習については、国語や理科、また市民科の中で、その時間で全員行かない場合もあります。複数で行って調べることもあります。様々な条件の中で、時には区立の図書館に行って調べることができない子では仕方ないということで、やはり力をつけなくてはいけないと思うのです。\nそういう意味では、各授業の中でも図書館の指導はしますし、社会科で調べ学習の中でやみくもにインターネットで調べても見つからないということも指導しますので、このような様々なバランスの中で教育をしていくということでご理解いただきたいと思います。"},{"i":86,"speaker":"安藤委員","text":"いろいろご答弁いただきましたが、やはり根本的に少ないというのは問題だと思うのです。世田谷区と杉並区では５日とあります。あと港区、大田区、渋谷区では４日ということで、２倍ぐらい配置しているわけではないですか。やはり教育施策を常々前面に押し出している品川区としても、このような現状でいいのかと私は思いますし、先ほどセンター長がまさにおっしゃったように、スタッフのお仕事は、本当はもっと授業で子どもたちに直接関わりながら調べ学習の支援などをしたいのでしょうけれども、たくさん仕事があるのです。それだけをやっていられない。そのとおりだと思います。開館やら閉館の業務やら、配架整理やらレファレンス、あと品川図書館との交換便の対応、教職員の相談、図書館だよりの作成、ディスプレイ、選書の補助、蔵書点検等々、もうとにかくすごく仕事があるわけですから、実際に時間を増やさなければ、スタッフが本当に学びの充実をする子どもに、そういった調べ学習の充実とかその支援をする時間が取れないという、ただでさえそういう現状なのですから、私はこれは増やしていく方向でぜひ努力をしていただきたいと思います。"},{"i":87,"speaker":"あくつ委員長","text":"ほかにございますでしょうか。"},{"i":88,"speaker":"吉田委員","text":"先ほどの質疑の中でも出てきたのですけれども、今すぐには増やせない原因というのは、やはり指定管理契約が５年間ということで、５年間に関しては動かせないということが主な原因なのかというのを確認したいのが１点です。\nそれから、それを前提としましても、今の新指導要領だと、教科書の中に主体的・対話的で深い学びが求められ、その深い学びとして学校図書館を計画的に利用し、情報活用能力の育成ということがうたわれているということですよね。各学年で学校図書館の利用・活用、情報活用にページが割かれているというこの状況、政策は新しくなったので、これに対応する司書の配置というのは当然検討されていると思うのですけれども、その辺についてはいかがでしょうか。\n今、ＩＣＴの活用ということで、先ほどご答弁の中にもあったと思うのですが、インターネットを使えばいろいろなことが調べられてしまうという言い方は変ですが、調べることができるのだけれども、やはりその情報について取捨選択する能力も、これからの子どもたちは求められていくのだと思うのです。もちろん、普通の授業の中で教員がその辺のことをきちんと学ばせるということも当然やられていくのだと思うのですけれども、やはりその中で学校司書が適切な資料の提供、それから子どもに合わせた資料の提供を行っていくことによって、その子の情報の選択能力といったことも進むのではないかと思います。\n今、タブレットも配られましたし、インターネットでの様々な玉石混交の情報の中で、それをちゃんと取捨選択する能力を伸ばすというのは、本当にもう喫緊の課題として求められているのではないかと思うのです。だから、教科書にこのような学校図書館の活用がうたわれたということと、それからＩＣＴなども含まれたインターネット上の情報の取捨選択能力ということを考える上でも、学校司書の役割は増しているように思うのですけれども、その辺についてのご見解を伺いたいと思います。"},{"i":89,"speaker":"吉田品川図書館長","text":"契約についてでございますけれども、こちらは学校図書館運営支援業務委託という形で、これは通常の委託業務で指定管理ではございません。これにあたりましては、平成３０年度から５年間の契約という相互評価方式の契約という形で、大きく仕様を変えられないところでございます。\nそれから、現在までの学校司書と学校、それからボランティア、これはかなり密接に連携して進めてきたところでございます。それぞれの今までの取組みの経緯もございますので、現状、このような状況となっているところです。今後、こちらの強化につきましては検討してまいりたいと思っております。"},{"i":90,"speaker":"吉田委員","text":"要は新指導要領に基づいて、今後はそれを強化していくという見解でよろしいのでしょうか、もう一度確認させてください。例えばＩＣＴでインターネット上の情報などを適切に読み解いていくような力量も、学校のそういう教育の中で求められていると思うのですが、その辺についての見解をもう一度伺いたいと思います。それは急がなければいけないのではないかというのがありましたので、そのことを改めて伺いたいと思います。"},{"i":91,"speaker":"矢部教育総合支援センター長","text":"委員がお話しになりました主体的・対話的で深い学びについてでございますが、既にご存じのとおり図書館だけですることではなく、すべての教科の中で、各学校活動の中で学ばせていくものなのでございますが、そこに図書館が有効活用されるということで、それはそのとおりでございます。\nただその一つの施設としては、図書資料は当然そこにあるものでございますので、担任もおります。スタッフがいない場合は担任とともに、または学年にもよりますが、児童・生徒相互にそれぞれ学び合うという機会としても大事なことなのではないかと思います。子どもたちは図書以外にも、ご指摘のＩＣＴもタブレットも活用できますので、様々な視点で、また機会としては市民科や各教科でリテラシーのほうも学んでもらいたいと考えております。"},{"i":92,"speaker":"吉田委員","text":"今、学校の現場で様々な教員の方たちが、やはり一緒に子どもたちのリテラシーを高めるための教育が行われているわけですが、先ほど、学校の教員は大変やることが多くて忙しいというのがありました。その中で適切に自分たちが子どもたちに教える力をつけるためにも、学校司書がこういう資料を研究したらどうかと提供することも図書館司書の役割ですよね。そこに専門性があるわけです。だから教員の方たちの子どもたちへの教育の専門性を、直接ではないけれども間接的にサポートするという司書の役割もあります。ですので、やはりこの教育を行う全体から見て司書の役割というのは、子どもたちが適切に学ぶ力をつけると同時に、教員の教育する力を高めるための適切な資料の提供とか、そういう役割もあると思います。\n今のままだと、例えば学校によっては教員の忙しさもあって、スタッフがいない時間は図書館が閉められていることもあると聞きます。学校の図書館は勉強の場でもあると同時に子どもたちの居場所、私自身はどちらかというと休み時間は外で遊びなさいという先生の目を盗んで、図書館に逃げ込んで本を読んでいたいという子どもだったので、そこに鍵が閉まっていたりしたら本当に悲しいだろうなと、そういう個人的な思いもあるのですけれども、ぜひやはり図書館というのは学びの場であると同時に、子どもたちの居場所としての機能を発揮してもらいたいと思っています。\nぜひ図書館司書がずっといてほしいと思うのですけれども、なかなかそれはこの陳情の中でも出ていますけれども、いきなりそれを実現するのは今までのご答弁を聞いても難しいということであれば、やはり規模の大きいどうしても生徒１人当たりで計算してみると配置が少なくなってしまう大規模の学校からの運用は必要だと思うのですけれども、改めてそこのご見解を伺いたいと思います。"},{"i":93,"speaker":"吉田品川図書館長","text":"何点かありましたが、スタッフがいない時間に図書館を閉めているというお話なのですけれども、図書館の委託契約の中においても、基本的には図書館を閉めるということは特にやっておりません。ただ、学校の管理上の問題で閉めるというケースがあるというふうに聞いてはおりますが、学校図書館として特にこちらの学校司書がいない時間帯に学校図書館を閉めるだとか、そういうことはお願いしていないところでございます。またその辺は、学校の図書委員だとか、またはスタッフだとか、いろいろな形でも学校では開けられるのかなと思っております。\nそれと、人数のところの問題でございますけれども、今後図書館の利用、その辺も含めまして、必要に応じて必要なところで検討してまいりたいと考えているところでございます。"},{"i":94,"speaker":"工藤指導課長","text":"運営スタッフがいない時の図書館の利用等につきましては、今図書館長からもありましたように、例えば、児童会・生徒会活動の中でいわゆる図書委員、図書担当の児童・生徒が休み時間に開館するであるとか、また授業の活動においても、鍵と管理をしっかりしながら教員が行うこともできたりいたします。また、資料の提供等につきましても、従前いる時はもちろん連携がありますけれども、例えばスクールサポートスタッフを介しながら必要な資料を整えていくであるとか、また学校支援地域本部でボランティアを募りながら、先ほども説明がありましたように読み聞かせなども行うなど、いわゆる学校司書を含めながら、様々な体制で図書館を利用した事業等が展開できるような体制は一定程度あるかと認識しているところでございます。"},{"i":95,"speaker":"吉田委員","text":"これ以上は水掛け論みたいになってしまうので最後にしますけれども、今、学校司書に司書の資格があるということは、やはり学校司書に求められている役割があるわけです。その役割を果たせるのは必ずしもその資格を持った人だけではないけれども、やはり必要だから資格があり、その人の配置というのが図書館に求められているのだと思います。そういう意味と、それから新しくより主体的で対話的な深い学びとかいう点でも、学校図書館の役割というのは重要になってきていると思いますので、ぜひ司書の勤務日数を増やして、せめて学級数の多い学校からということは検討していただきたいたいと思います。"},{"i":96,"speaker":"あくつ委員長","text":"ほかにございますか。"},{"i":97,"speaker":"松本委員","text":"今の質疑の中できちんと確認しておきたいのですけれども、区立の小・中学校で、昼休みおよび放課後に学校の図書館が開いていないということが実際に事実としてあるのでしょうか、お願いします。"},{"i":98,"speaker":"工藤指導課長","text":"実際開館日については、各学校、いわゆる生徒会活動、児童会活動の中で開館日を学校ごとに分けるであるとか、また放課後、特に中学校は勉強とか部活動などとの兼ね合いもありますけれども、委員会活動としていつ開館するかというのは各学校で定めておりますけれども、そういった意味で開いていない時間、あるいは場面もあろうかと思いますけれども、基本的にはそういった活動の中で、いわゆる学校司書がいるいないにかかわらず開館をするというのは活動の中で行っているということでございます。"},{"i":99,"speaker":"松本委員","text":"ずっと一貫して、品川区も全国もそうだと思うのですけれども、本を読みましょう、本を読みましょうということはずっと言ってきたところだと思うのです。自分が小さい頃を考えると、学校の図書館が少なくとも昼休みに開いていないというのは、私が育った環境ではなかったのです。子どもに本を読みなさいということを言っている中で、昼休みに図書館が開いていないという状況を、教育委員会としては、それは別に問題ないと思われているのか伺います。"},{"i":100,"speaker":"工藤指導課長","text":"今ご質問いただいていますけれども、問題があるかないかというところの観点で言えば、それは開くべきであると認識しておりますし、それは活動の中で無理のない範囲でという言葉はもちろんつきますけれども、様々学校は工夫してできるだけ開くような体制で行っていくと認識しています。"},{"i":101,"speaker":"松本委員","text":"そうは言っても現実問題として開けていないというのは、私は区民の方から聞いてちょっと衝撃を受けたのですけれども、開けていないという状況はやはり問題だと思っていて、それについて何か今改善のための対策はされているのでしょうか。"},{"i":102,"speaker":"矢部教育総合支援センター長","text":"これまでの回答のとおり、特段閉めているというところを私どもの情報では得ていませんし、特に休み時間は開放して、先ほどの委員のお話のとおり、学習だけではなくて、居場所として開放しているケースが多いと認識しております。また、様々な機会に私たちも話すことはあると思いますので、実態をつかんで、いろいろなところの教育にも関わると思いますので、図書館の活用については今後も進めてまいりたいと考えます。"},{"i":103,"speaker":"あくつ委員長","text":"ほかにございますか。"},{"i":104,"speaker":"松澤委員","text":"２点ほど確認したいのですけれども、例えば学校図書館というのは子どもたちが利用しますよね。その子どもたちに対して、学校図書館はどうですかというようなアンケート、図書館の利用をどう思っていますかというのは、教育委員会で聞いたことはあるのでしょうか。教えてください。"},{"i":105,"speaker":"吉田品川図書館長","text":"利用について子どもに対するアンケートにつきましては、最近では記録にはないところでございます。ただ、スタッフ等につきましては毎年、学校司書とどのようにうまく連携が取れているかとか、それに対する問題はあるかというようなことは、学校に対しては、学校の司書教諭の先生だとかを含めまして、そういったアンケートは実施しているところでございます。"},{"i":106,"speaker":"松澤委員","text":"それともう一つ、要は学校図書館の利用率は大体どれぐらいの児童・生徒が利用しているか。入ってくる人数というのは難しいと思うのですけれども、貸出本数であったりとか、ちょっと細かい話ですけれども、そういった把握というのも教育委員会がするのか、学校の中でやるのか分からないのですけれども、そういうのがあるのだったら、確認させてください。"},{"i":107,"speaker":"吉田品川図書館長","text":"学校によっても様々なので、利用率という形だと、なかなか何を母数にとって何をというところが不明なので、例えば一定程度年間にどのぐらい貸出しがあるだとか、そういうところの数値についてはつかんでいるところでございます。人数が多い学校と少ない学校では、貸出しのところに若干差があったりというのは現状も出ているところでございます。"},{"i":108,"speaker":"矢部教育総合支援センター長","text":"正確なデータは分かりませんが、個人での利用についてはなかなか把握できないのですけれども、基本的には図書の時間がございますので、学校図書館の利用は全員に近い数でされていると認識しています。"},{"i":109,"speaker":"あくつ委員長","text":"ほかにございますか。"},{"i":110,"speaker":"つる委員","text":"今、松澤委員から、児童・生徒の声も聞いたほうがよろしいのではないかと、私も同様の視点で、そこが実際どうなのかと思っていたところです。２年前に同様の陳情が出て、その時の図書館長からのご説明の中で、５年、１０年という具体的な年限がご発言としてあって、品川区で言うところのスタッフが全日というような体制を検討していくということが示されて、今、そう考えると３年なのです。あと２年で５年目、あと７年で１０年目という形になる。それが５年なのか１０年なのかというのは、先ほど来質疑でもあるとおり、学校長が学校図書館長というところで、それぞれの児童、そして生徒、教職員の方も当然替わるでしょうし、学校長も替わる。そういう中でのハードとしての各学校の図書館の運営というところでは、いろいろな角度・観点からの検討に際しての時間がかかるのかなと。そういう受けとめを２年前の質疑の時に確認しながら思ったところですし、今日の質疑でも思ったのですけれども。\nやはりやってみなければ分からないというところは幾らでもあると思うのですけれども、ただ制度や仕組みを整えて、制度や仕組みを児童・生徒にはめ込むというのは、やはり実際、誰のために学校図書館があるのか。それは教職員の方も当然授業に必要なものという観点も当然含まれるわけですけれども、やはり最大の部分というのは、児童・生徒にとっての図書館という視点が本流なのかなとなったときに、やはり児童・生徒が今のこの品川区の図書館を利用できる環境について、どう思っているのかという声が一番重きになってくるのだろうと思う中では、これはまさに日常の授業、または休み時間も含めた中で、担任の先生はじめ教職員、学校長がそれを受け止めていただいているという認識でいます。\nその中で、これは指導課なのか教育総合支援センターなのか分からないですが、図書館のこの辺りについての具体的なそういうお声というのはあるのかどうか。これはアンケートとかそういう話ではなくて、個別のそういう状況の中でそういう声を聞いたことがあるとか、把握しているかしていないかは別にして、聞いたことがあるのか、そういう部分であれば教えてください。"},{"i":111,"speaker":"矢部教育総合支援センター長","text":"各学校の中では特に、お話にもありましたが、委員会活動を中心にお子さんの様子を撮って、スタッフが図書館だよりに出してくれる場合もありますので、その内容を読むと、特に図書の人気のあるランキングなどはよく出ます。また、それを給食の放送中に出していたり、また先生たちの好きな本、心に残った本などの一端を紹介したりということをしておりまして、子どもたちは読み聞かせについても大変集中して聞いておりますし、それぞれの各学校の中で、実態に合わせて大変充実しているように認識してございます。\n読書の冊数についても、貸出冊数についても各学校でそれぞれカウントしていると認識しています。"},{"i":112,"speaker":"つる委員","text":"ありがとうございます。そういう意味で、どこまでもやはり児童・生徒の声を中心として、基本として、いろいろな充実をさせることも含めて、やはり体制を考えていただくということが大事なのかなと思うのです。\n当然環境が整っていれば、そこに来る機会も増える、そういう誘導の仕方というのもあるのでしょうが、やはりハードとしての整理、本の冊数だとか選書だとか、そういうことはこれまでもずっとやってきているとは思うのですけれども、ではその最終というか、児童・生徒が本に触れるきっかけを作る非常に重要な役割というのが図書館にいらっしゃる方、スタッフだと思うのです。\n私も本屋出身ですから、図書館というのは対極なのか仲間なのかどちらか分からないのですけれども、本屋としては本を買ってほしい。図書館というのは本を買わなくても読めるので、図書館が充実していると本屋はきつくなるのかなとか、そういう観点で前職の時は思っていたこともあります。やはり本に触れる機会というのは、私も店員の時に聞かれれば、自分の限られた知識の範囲の中、経験の中で、そういうことであればこういう本がありますという情報提供というのはやる。そういうふれあいの中で、その方の人生とか背景とかを聞く中でいろいろな交流が生まれるということが、恐らく図書館でも展開されているのかなと理解する中では、いろいろなところにそういう図書と出会う機会、図書を通じたその子どもの人生の応援になるような機会というのがやはり必要なのだろうと。\nそれは学校としては当然図書館というところがあるわけですが、当然地区館もあるわけです。その子どもにとって居やすい環境というのは幾つかあるというのは重要なことであるし、そこにいろいろな世界にすぐ瞬時に飛んでいける本があるということも大事。そういうことを考えると、所管が違うのですが、例えばすまいるスクールとか児童センターには一定程度巡回で書籍を置いていただいたりしていると思うのです。そういう部分では、いろいろな形で児童・生徒が書籍に触れる機会というのを今後も増やしていくという観点は大事なのかなと。\nそうすると、制度だけの部分で図書館にぎゅっとフォーカスするのではなく、いろいろなところで子どもたちが図書に触れる機会を広げていくという観点も必要なのかなと考えた時に、それは居場所の話とか、ただ地区館などでもよくあるところです。自治体でいろいろなそういう位置づけもあったりするところなので、あくまでも充実させていくということはすごく重要なことなのですが、どこまでも児童・生徒の視点、立ち位置で、何をどう充実させてあげることが子どもたちにとって将来の栄養になっていくのかというところをやはりやっていただきたいと思うのです。急いで何か制度だけ、またスタッフのことだけを展開していくというのは、ちょっとまた視点がずれてきてしまうのかなと思うわけです。言葉と生きていくという表現があるわけですけれども、まさに図書というのはそうなのです。ですから、その部分で考えていただきたい。\n最後に５年、１０年というのもありますけれども、先ほど来若干質疑があったかもしれませんが、その方向性、児童・生徒の声も含めて、品川区の場合はそのスタッフまたボランティア、それはコミュニティ・スクールも含めてだと思うのですけれども、今どのような現状にあるか。現時点でお答えできる部分でいいので、それを最後教えてください。"},{"i":113,"speaker":"吉田品川図書館長","text":"子どもに本に触れてもらうということは一番重要なことで、これからそういう機会を十分に作っていくというのも図書館の役割だと思っております。そのためには、まずは例えば各学校では広報活動だとか、図書館だより等を作りながら進めていっているところでございます。\nそれから、５年、１０年、今後のところですけれども、積極的に図書館として各学校図書館の運営に関わりながら、学校の自主性も尊重しつつ、委託業者にすべて任せるというのではなくうまく協力しながら、今後拡充の方向で考えていければと、今検討しているところでございます。"},{"i":114,"speaker":"あくつ委員長","text":"ほかにございますか。"},{"i":115,"speaker":"吉田委員","text":"今のご答弁で、委託事業者とうまくというようなお話がありましたけれども、先ほどはごめんなさい、指定管理ではなくて委託契約でしたね。委託契約だった時の委託の主体というのは各学校になるのでしょうか。それとも教育委員会でしたか。そこを確認させてください。\n委託契約となると、それなりに契約上の縛りが出てくるのかなと思います。よく世間一般に言われるのは偽装請負とか偽装委託とかになって、その現場の人たちと、それから委託契約の範囲のことで結構トラブルが起きたりしていますね。それが少し気になったのですが、それだけ確認させてください。"},{"i":116,"speaker":"吉田品川図書館長","text":"現在委託につきましては、月ごとに副校長や図書館担当教諭、受託業者の責任者と実際の運営スタッフ、このチームによりまして、作業企画会議というのを毎月開いております。この中で、運営方針、運営内容等を定めて活動しているところです。\nその中には、必ず直接運営スタッフへの指示という形ではなくて、必ず運営事業者の責任者が同席し、そこの承諾の下という形をとっておりますので、一般的な意味でも偽装という形には当てはまらないものと認識しているところでございます。"},{"i":117,"speaker":"吉田委員","text":"分かりました。ただ、結局そういう会議の中で決められたことに基づいて、現場の人間は、学校側も受託した運営事業者もその中でしか動けないというのは、それはやむを得ないというか、そういうことですね。臨機応変にその場で、例えばボランティアの方がそこで協議をして何か考えるということは、やはり難しいのですよね。"},{"i":118,"speaker":"吉田品川図書館長","text":"臨機応変ということなのですが、必要に応じてという形にはなりますけれども、運営スタッフのほうから現場の責任者に連絡をいたしまして、また現場の責任者と学校長、副校長や担当の司書教諭と話し合って、またそこで決まった内容で委託のスタッフにおろす。この辺につきましては、現在も臨機応変に行っているところでもございます。"},{"i":119,"speaker":"あくつ委員長","text":"それではよろしいでしょうか。ほかにご発言がないようですので、これで質疑を終了いたします。\nそれではまず、令和３年陳情第５８号の取扱いについてご意見を伺いたいと思います。\n継続にする、あるいは結論を出す、どちらかご発言願います。また、結論を出すのであれば、その結論についてもご発言ください。\nそれでは、品川区議会自民党からお願いいたします。"},{"i":120,"speaker":"松澤委員","text":"本日結論を出すでお願いいたします。不採択でお願いいたします。\n理由は、学校図書館、今いろいろお話を聞きました。私も子どもを持つ親として、学校図書館というのは大変重要だということは認識しております。つる委員もお話しされましたけれども、やはり利用する子どもたちが、学校図書館というのをどう思っているかというのは、私は本当に大切なことなのかなと。新指導要領で図書館を利用するから、ではしなさいではなくて、子どもたちが本当にどう思っているのかとか、そういった把握というのもしっかりしないといけないと思うのが１点。\n開かれた学校の中で、学校司書だけではなく、コミュニティ・スクールである、スタッフスクールである、ボランティアである、そういう方がやはり参加されることが、おっしゃいました開かれた地域の学校という部分にもつながると思います。まだまだ総合的な検討があると思いますので、不採択とさせていただきます。\nしかし、その契約という部分の際にいろいろな課題が出ていると思います。そういうのをしっかりとヒアリングして、対策をして、次につなげていただけたらと思います。要望です。"},{"i":121,"speaker":"つる委員","text":"本日結論を出すで、態度は不採択でお願いいたします。\n先ほど質疑の中でも確認させていただきまして、２年前に同様の陳情が出されて、その時の冒頭の図書館長の説明の中でも、先ほど確認させていただいたその段階で５年、１０年という一つの目途を定めた上で、その図書館の充実を図っていくということが示されている中で、当時の陳情については、文教委員会では不採択になっておりました。\nそういう中で、今質疑もいろいろございました。ただ、やはりどこまでも児童・生徒にとって最善の状況というのが、これは当然有資格とか無資格は関係なく、やはり品川区が体制を取っておられる地域との学校を作り上げていく、子どもを見守っていく、育てていくという観点からするならば、様々な方に図書館運営についても関わっていただいて、作り上げていただくという形を今品川区がとっている中で、そういう意味での図書に関わる子どもたちに関わる環境の充実、その視点でしっかりと進めていただきたいと思います。\nなので、２年前の時の陳情でも不採択になっている中でも、今図書館長からるるご答弁あった中で、粛々と検討していただいているという現状もあります。そこも含めて、またその資格者とかになってくると、また今度は図書館全体、運営の財政的な部分も含めていろいろな観点の検討が必要になってくる。それではやはり子どもたちにとって図書に触れる機会を充実させていくということが逆に遅れてしまってもよろしくないというところでは、今、品川区がとっていただいている様々な方の関わりの中で、体制を充実させていただくということをしっかりとさらに力を入れてやっていただきたいと思います。"},{"i":122,"speaker":"安藤委員","text":"本日結論を出すで、採択を主張したいと思います。\nやはり先ほどの質疑の中でもありましたけれども、メディアリテラシーの問題ですとか、新しい学習指導要領の問題とかで、やはりもう学校の図書館に図書館司書、学校図書館に求められる状況は大きく重要性が増しています。状況が変わっていると思います。これからやはり重要な２１世紀型の学力、探求と共同の学び、アクティブ・ラーニングなどをすべての子どもに保障するためには、やはり学校図書館の活用の充実は大切で、そのための専門スタッフの充実は、私は不可欠だと思います。\nそれと、様々図書に触れる機会を作るということと、学校図書館の本丸の人的体制を強化していくというのは決して矛盾するものではないし、対立させるものでもないと思いますし、ここをしっかりやっていくことは私はすごく重要だと思います。\nあと、質疑の中で委託契約の話がありましたけれども、２年前にも質疑があったかもしれないですが、平成３０年からの委託契約ということで、考えてみると今平成に直すと３３年なので、あともう２年で切れるわけで、それほど先ではないと思うのです。先ほど拡充の方向で考えていければという図書館長のご答弁もありましたけれども、ぜひそういった検討を後押しするためにも、２年前は２年前で、今回は私たち今のこの委員会で、これをしっかり採択していくことが私は重要だと思っております。"},{"i":123,"speaker":"吉田委員","text":"生活者ネットワークとしても本日結論を出すということで、採択を主張したいと思います。\n様々な議論が行われました。先ほどの私の意見の出し方とか質問の仕方がまずかったのかなと思うのですけれども、新指導要領に基づく教科書というところから話を始めてしまったので、あたかも子どもたちの意向は無視して、それだからそうしましょうというふうな意見に聞こえてしまったかもしれませんけれども、これはあくまで区側がどういう資源を子どもたちに提供するかという視点で、この指導要領の内容については、生活者ネットワークとしてもすごく賛同できるものですので、ぜひそれは進めていただきたいと思って、そういうふうに言いました。\n先ほど、私自身もどちらかというと外で遊ぶよりも図書館にいる人だったのですけれども、今は子どもたちもみんな調べ学習とかが求められていますね。私は自分が調べ学習でぽんといきなり図書館に行かされたら、とても困るタイプだったのです。やはりそこは、子どもにとっても快適なすごく夢のある図書館になるかどうかというのは、そこで読書をさりげなくサポートしてくれるような司書の存在、私の場合はそういう司書がいる学校だったのですけれども、それはすごく大きいし、私のように扱いにくい子どもに、教員がこの子にはどういう指導をしたらいいだろうかという時に、適切な教員がサポートしてくれるような司書の存在というのも大変重要だと思っています。\nどんどん自分で積極的に勉強していける子どもたちばかりではありませんので、そういう子どもたちがいつでも図書館に行けて、いつでもサポートが受けられるというのは、学ぶ力を育てる上でもすごく大きいと思いますので、ぜひこの陳情を区議会として採択して、品川区の教育委員会が頑張っているのは今ご答弁で分かりましたけれども、それを後押しするためにも、採択をしたいと思います。"},{"i":124,"speaker":"松本委員","text":"本日結論を出すで、採択でお願いいたします。\n理由といたしましては、一般論で申し上げると私が所属する日本維新の会、この学校司書の問題については、ＡＩというような話も国政のほうにおいてはしております。この学校司書の役割について、きちんと見直して整理するということが一般論として必要なのは、これは私もそう思っています。\nただ一方で、各自治体における考え方というのは、これは各自治体で見ていかなければいけないと考えておりまして、今回の陳情の最後のところにも出ておりますけれども、世田谷区、杉並区は週５日というところもある。その中で、品川区は２００５年から２.５日ということをやっているのですけれども、ここにやはり開きがある。\n考えなければならないのは、平成２７年でしたか学校図書館法が改正されて、この学校司書の明記がされて、努力義務もしっかりと出ている。そのような状況の中で体制が変わっていないというのは、少しやはり考えるべきところがあるのではないかと私は思います。\n品川区に関しては、子どもの人口もこの間増えているという状況の中で、これもやはり考慮していかないといけないと思っておりますし、また先ほど来話も出ておりましたが、この学校の働き方改革もすごく重要だと考えております。学校の教員の皆さんが、では適切な図書を自分たちの授業とは別に選んでいくという体制が果たして今できているのかといったら、そこは図書の専門家という方たちがしっかりと選んでいく、あるいは学校の教員の方たちが自分たちで資料を探すというのも大変ですから、こちらもやはり図書の専門家の人たちからしっかりと、こういう書籍がありますと、あるいはこういう資料がありますというアドバイスを受けるというのは大事だと思います。\nあと、先ほどやや答弁がはっきりとした事実としては分かりかねるところもあるのですけれども、やはり私は区民の方から、学校の図書館が放課後、または昼休みに開いていないということがあるということを伺い、これもやはり大きな問題だと思っています。これも一般論ですけれども、学校のスポーツについては、オリンピック・パラリンピックもあって、とにかくスポーツは推進しよう、推進しようという流れがある中で、ではスポーツが苦手な人たちが学校の中でどのように居場所があるのかというのは、これは少し大きな目線で考えるところが必要かなと思っています。\n私自身もスポーツは苦手で、教室の中では結構問題も多い児童だったので、授業中に抜け出して、図書館に行くこともありました。これもやはりその経験があったからこそ、逆に不登校にならなかったというところもあります。これは必ずしも学校司書の問題だけではなくて、ほかのボランティアのスタッフとか、そういうふうなやり方はあるとは思うのですけれども、ただ一方で、冒頭に申し上げたこの陳情に出てきている他区との状況から開きが、もちろんすべてが５日間というわけではないですけれども、やはり５日と設けている区がある中で、２.５日というのはやはり少ないと思うところでございますので、しかも５日にしてくれという陳情ではなくて、学級数の多い学校からでも週に５日人がいる体制というふうな、必ずしもトップになろうということを目指しているわけではないと考えますので、私としてはこの陳情を採択と主張させていただきます。"},{"i":125,"speaker":"あくつ委員長","text":"それでは、本陳情につきまして、結論を出すとのご意見でまとまったようでございますので、そのような取扱いでよろしいでしょうか。\n〔「異議なし」と呼ぶ者あり〕"},{"i":126,"speaker":"あくつ委員長","text":"それでは、本件は結論を出すことに決定いたしました。\n先ほどそれぞれの方のご意見を伺いましたので、本陳情につきましては、挙手により採決を行います。\nそれでは、令和３年陳情第５８号、品川区立学校図書館の充実に関する陳情を採決いたします。\n本件を採択とすることに賛成の方は挙手願います。\n〔賛成者挙手〕"},{"i":127,"speaker":"あくつ委員長","text":"採択３名、不採択３名です。可否同数であります。\nよって、委員会条例第１５条の規定により、委員長が裁決いたします。委員長といたしましては、本陳情に対しまして、不採択と裁決いたします。\nでは、私からも一言申し上げます。先ほど様々な質疑を頂戴し、拝聴いたしました。各委員からもいろいろなご自身の思い出が語られました。私も田舎の公立の小学校出身です。図書室で片っ端から本を借りて、江戸川乱歩、コナン・ドイル、様々片っ端から借りて、それを学校の帰りに、私は地方の田舎でしたから、学校の行き帰りにリュックサックを背負って本を読んでいたら、二宮金次郎みたいな子どもがいると近所で大評判になりました。先生に呼び出されて怒られましたけれども、それぐらい、私としては居場所として学校の図書室というのは非常に重要なところだと思っております。\n国会議員の秘書もやっておりましたので、国立国会図書館のリファレンス機能のようなものを活用させていただいて、図書館というものの機能の重要性というものはある程度は自分なりに理解しているつもりです。\nただ、今回のこの陳情に関して、先ほどの質疑の模様を伺っていると、品川区としても拡充の方向で、長期的な形で検討している。これは前回の時もそのようなご答弁があったということで、契約の内容について今仕様が決まっているので、今すぐにというわけにはいかないというように私は理解をいたしました。というところで、現段階においては、採択は難しいのかなと私は理解をしております。\nよって、本件は不採択と決定をさせていただきました。\n以上で本件を終了し、請願・陳情審査は一旦これまでといたします。\n会議の運営上、暫時休憩いたします。\n○午前１１時５７分休憩\n○午後 １時００分再開"},{"i":128,"speaker":"あくつ委員長","text":"休憩前に引き続き、文教委員会を再開いたします。\n────────────────────────────────────────────\n１ 議案審査\n(1)第６６号議案 品川区立児童センター条例の一部を改正する条例\n(2)第６７号議案 品川区立保育所条例の一部を改正する条例"},{"i":129,"speaker":"あくつ委員長","text":"それでは、予定表１の議案審査を改めて行います。\n初めに、(1)第６６号議案、品川区立児童センター条例の一部を改正する条例、および(2)第６７号議案、品川区立保育所条例の一部を改正する条例を一括議題に供します。\n本件２議案につきましては、関連する内容のため、一括して説明、質疑を行い、その後、議案ごとに採決を行いたいと思いますので、よろしくお願いいたします。\n本件につきまして、理事者より一括してご説明願います。"},{"i":130,"speaker":"初貝保育教育運営担当課長","text":"それでは、私から、第６６号議案、品川区立児童センター条例の一部を改正する条例、第６７号議案、品川区立保育所条例の一部を改正する条例について、一括してご説明をいたします。資料をご覧ください。\n初めに、資料の訂正をお願いいたします。\n２、改正内容、（１）一本橋保育園・児童センター部分の地図のすぐ上の米印の部分でございますけれども、令和３年３月１日から休館となっておりますが、正しくは令和４年でございます。令和３年を４年へ訂正をお願いいたします。申し訳ございません。\nでは、内容の説明に移らせていただきます。\nまず、改正の理由でございますが、今回の保育園・児童センターの建て替えに伴う移転によりまして、所在地の変更などについて改正するものでございます。\n次に、改正内容ですが、（１）一本橋保育園・児童センターですが、現在老朽化した施設の建て替えを実施するため、一本橋保育園は荏原第四中学校の跡地に移転します。所在地は品川区大井２丁目２５番１号から品川区豊町３丁目５番３１号に変更となります。\n施行期日は、令和４年４月４日です。なお、児童センターは、令和４年３月１日から令和６年３月３１日まで休館をいたします。\n続いて、（２）東大井保育園・児童センターですが、現在、老朽化した施設の建て替えを実施しており、このたび、東大井公園内の仮施設に移転しておりましたが、改修工事終了後は移転前の場所に戻ります。所在地は品川区東大井３丁目４番４号から、品川区東大井１丁目２２番１６号に変更となります。\n施行期日は、令和４年９月２０日です。\n第６６号議案、品川区立児童センター条例の一部を改正する条例、第６７号議案、品川区立保育所条例の一部を改正する条例についての説明は以上でございます。"},{"i":131,"speaker":"あくつ委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑等がございましたらご発言願います。"},{"i":132,"speaker":"安藤委員","text":"まずは、東大井の児童センターについてですが、建て替え前と後では、何か機能面や利用面において変わったことはあるのでしょうか。伺います。\nそれと、一本橋保育園のほうですけれども、ここは保育園の民営化対象園だと認識しておりますが、何園目でいつからの計画なのか伺いたいと思います。今ある区立保育園を民営化することは、保育士が専門性を積み重ねる観点も奪うし、結果として区内の保育の質の低下につながることからやめるべきなので、公立は維持すべきだと思うのですけれども、この移転、現在、一本橋保育園のほうのこの建物なのですけど、耐震性には問題があるのか伺いたいのと、それと児童センター部分の機能が移転しないのではないかというように見えてしまうのですけど、この機能はどうなるのか伺いたいと思います。"},{"i":133,"speaker":"廣田子ども育成課長","text":"まず、東大井児童センターの建て替え前後の変更点等なのですけれども、レイアウトはもちろん、児童センターは今まで階段で３階以上まで上がるというところだったのですが、エレベーターがつきまして、エレベーターでベビーカーを乗せたりとかして、子ども連れでも上がれるように利便性が上がったというところが大きな変更点となっております。\nエレベーターを取り付けた関係もございまして、若干、床面積は狭くなってしまうのですけれども、２階も少し使わせていただいて、２階と４階に工作室や図書室など落ち着くような雰囲気のところをつくったり、京急の電車が見えるようなビューカウンターをつくったり等、工夫をしまして、狭くなった分、子どもたちが喜ぶような仕組みを入れたというようなところが変更点となっております。\n続けて、一本橋の児童センターにつきましては、荏原第四中学校のところには入り切れないというところが一つと、東大井児童センターにつきましては、東大井児童センターを含めた１３館につきましては、虐待等対策なども含めまして１３地区を拠点館として、網羅しているという館なのでございますが、一本橋については分館という扱いになっておりますので、仮設が建てられるにこしたことはなかったのですけれども、今回はちょっと場所が取れないということで休館をするという判断をしたものです。移転は行わずにお休みをするという判断をしております。"},{"i":134,"speaker":"初貝保育教育運営担当課長","text":"今、ご質問をいただきました、民営化に関することでございますけれども、まず、民営化はこの一本橋保育園に関しましては４園目という形になりまして、時期は令和６年度から予定しております。\n続いて、一本橋保育園の現在の建物の耐震性の問題ですけれども、耐震性の部分には問題はございませんが、かなり築年数もたっておりまして老朽化が進んでいるというようなところで今回、改修を進めているところでございます。"},{"i":135,"speaker":"安藤委員","text":"では、一本橋の児童センターのほうは、一旦休みますけど、また建て替えた後に継続するということで理解しました。\nそれと、４園目の保育園部分は民間委託するということなのですけども、それで耐震性には問題ないということなのですが、なぜ耐震性には問題ないのに、これから民営化するというふうに分かっている保育園を建て替えるのかという、その理由をもう少しお伺いさせていただきたいと思います。\nあと、この一本橋保育園の建て替え計画を引き合いに、さきの決算特別委員会で質疑があって、自民党の議員から、園庭を持つ区立保育園の転用を求めるような質疑があったのですけど、何か総合的に検討していくというふうな答弁がありましたが、今やはり、隠れ待機児は除外されて実態を反映していない数字の上で、さらにゼロでもないということもあるし、非正規労働者や、これから職に就きたいという親もほとんど入れないという状況も全く解消されていませんし、保育園の転用というのを私はやるべきではないかと思うのですけど、一本橋保育園は４園目ということですが、５園目以降も保育園の民営化を進める考えなのかということと、あとは転用について、認可保育園の転用などについては、今どんな検討をしているのか伺いたいと思います。"},{"i":136,"speaker":"初貝保育教育運営担当課長","text":"幾つかご質問いただきました中で、まず、耐震化に問題がないのになぜ建て替えるかというところでございますけれども、区立園のほうは全体として多くの保育園が築５０年を超えるような状態になっております。建て替えに関しても、小学校などと違いまして、園庭を使って建て替えというところはちょっとできないところでございますので、建て替えができるタイミングで順次建て替えをする必要があるというような認識の下、建て替えをしているというようなところでございます。\nまた、５園目以降の民営化というところでございますけれども、今現在では、５園目というところまで民営化というところが決定しておりますが、６園目以降というところに関しましては、まず５園の民営化の状況を検証して、その後、そういったところも含めてどうするかというところで、まずはこの、今民営化されているところの検証をしていくというようなところで考えております。\n認可保育園の転用というところでございますけれども、保育園に関しましては、全体の保育所であったり、そういったところも見極めながら、適切な保育園の配置を今後もしていくというようなことで考えております。"},{"i":137,"speaker":"あくつ委員長","text":"ほかにございますでしょうか。"},{"i":138,"speaker":"吉田委員","text":"先に東大井の児童センターのほうを伺います。新たな機能というところでエレベーターがついたということで言うと、バギーにお子さんを乗せたお母さんなどには利便性が上がるのはいいなというふうに思うのですけども、一方で、児童センターというのはやはり若者というか中・高生などの居場所としての機能も持っていると思います。それで、広さのことがあるので、必ずしも全部十分になることは難しいのは理解しているのですけども、その辺の機能の充実というのはなかったのか伺いたいと思います。\nそれから、一本橋の児童センターは分館ということで、この建て替えの間は休館ということなのですけども、でもやはり使っていた、利用していた子はいると思うのです。そういう子への、ざっくり言うとフォローになると思うのですが、例えばこういうような児童センターで比較的近いところがあるよとか、そういう情報提供とか何かそういうことはあるのか伺いたいと思います。"},{"i":139,"speaker":"廣田子ども育成課長","text":"東大井児童センターについては、もともとあまり大きい館ではないのですけれども、中・高生等の使い勝手というところでは、今までバンドとかもできるような形では運用してやっていたのですけど、防音のお部屋がきちんとしたところがなかったので、防音設備のあるスタジオをつくりまして、あと隣のフリースペースとの間に窓があって、バンドをやっているところを小学生や中・高生等も見られるところをつくったことと、屋上に、コートが半分ぐらいとバスケットのゴールがありますので、中・高生はそこで３対３みたいなものができるというのも特徴で、また、もともと京急線のガードの近くだったので、鉄道が好きな子どもたちが電車を見ながらジオラマ作ったりする、一定程度のお子さんたちがおりまして、その辺りは小学生から中・高生までというところで、救えているのかなと、本当にもともと狭いのですが、何とかやりくりして工夫はさせていただいたところでございます。\n一本橋児童センターについては、残念ながら仮設が造れなかったのですが、大井倉田児童センターが３００メートルぐらい、滝王子児童センターと南ゆたか児童センターが８００メートルぐらいというところで、南ゆたか児童センターを工事したときもお使いの方は、近隣の児童センターをお使いいただいていたので、閉める前にはご案内等をきちんとさせていただこうと考えてございます。"},{"i":140,"speaker":"吉田委員","text":"ありがとうございます。児童センターの機能については、スペースの制約がもう本当に分かっていますので、なかなか難しいと思いながらも、やはり若者にとってもとても重要な居場所ですし、そこのスタッフとのやり取りが子どもたちにとってはやはり、学校の先生とか親とは違う大人というようなやり取りで、すごくそこをお互いに、子どもたちのほうも求めていたり、それからスタッフの皆さんも、しばらく顔見ない子について気にしてくださったりという、私たちが求めている子どもの意見聴取の役割を果たしているという、とても評価していますので、今後もこういうことがあったらぜひ、子どもたちとか親子連れの方たちだけではない、若者の居場所としての機能も、検討してくださっていると思うのですけど、ぜひ今後も検討していただきたいと思います。休館中のフォローについては、ぜひ丁寧にやっていただくようにお願いいたします。"},{"i":141,"speaker":"あくつ委員長","text":"ほかにございますでしょうか。\nほかにご発言がないようですので、これで質疑を終了いたします。\n採決に入ります前に、まず、第６６号議案、品川区立児童センター条例の一部を改正する条例につきまして、各会派の態度を確認いたします。\nそれでは、品川区議会自民党からお願いいたします。"},{"i":142,"speaker":"松澤委員","text":"賛成します。"},{"i":143,"speaker":"つる委員","text":"賛成です。"},{"i":144,"speaker":"安藤委員","text":"東大井保育園等の移転は、老朽化による建て替えに伴う移転なので賛成ですが、一本橋保育園の移転はやるべきではない。区立園の民営化を前提にして、改築してきれいな保育園を民間に用意して民営化を進めていくための住所変更ということなので、賛成できません。したがって、全体の態度としては反対となります。"},{"i":145,"speaker":"吉田委員","text":"賛成します。"},{"i":146,"speaker":"松本委員","text":"賛成です。"},{"i":147,"speaker":"あくつ委員長","text":"それでは、これより第６６号議案、品川区立児童センター条例の一部を改正する条例について採決いたします。\n本案は挙手により採決いたします。\n本案は、原案のとおり決定することに賛成の方は挙手を願います。\n〔賛成者挙手〕"},{"i":148,"speaker":"あくつ委員長","text":"賛成多数でございます。\nよって本案は原案のとおり可決決定いたしました。\n次に、第６７号議案、品川区立保育所条例の一部を改正する条例につきまして、各会派の態度を確認いたします。\nそれでは、品川区議会自民党からお願いいたします。"},{"i":149,"speaker":"松澤委員","text":"賛成です。"},{"i":150,"speaker":"つる委員","text":"賛成です。"},{"i":151,"speaker":"安藤委員","text":"先ほどの態度と同じなのですが、こちらは進めるべきではない。区立保育園の民営化を前提として、改築してきれいな保育園を民間に用意して、民営化を進めていくための住所変更ということで賛成できないということで、全体としてこちらは反対となります。"},{"i":152,"speaker":"吉田委員","text":"賛成します。"},{"i":153,"speaker":"松本委員","text":"賛成です。"},{"i":154,"speaker":"あくつ委員長","text":"それでは、これより第６７号議案、品川区立保育所条例の一部を改正する条例について採決いたします。\n本案は挙手により採決いたします。\n本案は原案のとおり決定することに賛成の方は挙手を願います。\n〔賛成者挙手〕"},{"i":155,"speaker":"あくつ委員長","text":"賛成多数でございます。\nよって本案は原案のとおり可決決定いたしました。\n以上で本件を終了いたします。\n────────────────────────────────────────────\n(5)第６４号議案 令和３年度品川区一般会計補正予算（歳出 文教委員会所管分）"},{"i":156,"speaker":"あくつ委員長","text":"次に、(5)第６４号議案、令和３年度品川区一般会計補正予算（歳出 文教委員会所管分）を議題に供します。\n本件につきまして、理事者よりご説明願います。"},{"i":157,"speaker":"山下子ども家庭支援センター長","text":"それでは私から、第６４号議案、令和３年度品川区一般会計補正予算（歳出 文教委員会所管分）につきまして、ご説明いたします。\n補正予算説明書の１４ページをご覧ください。\n３款民生費、２項児童福祉費、２目子ども家庭支援センター費に５４０万円を追加し、計を５４２億１,０４４万６,０００円とするものでございます。\n右側１５ページ、歳出の内容でございますけれども、新型コロナウイルス感染症対策、養育困難児童支援事業の委託料として計上しております。\n続いて関連資料によりご説明いたします。文教委員会にご提出していますＡ４、１枚の資料のほうをご覧ください。\n１、事業概要でございますが、子育て家庭において保護者が新型コロナウイルスに感染し、入院等が必要になった場合に、養育が困難となる児童の支援体制を整えるものでございます。\n児童の居所または区の指定する施設で児童をお預かりし、期間中、保育サービス事業者または宿泊事業者に支援業務を委託し、定時検温等を含めた子どもの見守りを行ってまいります。\n２、利用対象者につきましては、下記の要件を満たす児童としまして、（１）から（３）に記載のとおりです。\n３、実施予定場所は、利用対象者の居所またはファミーユ西品川子ども未来部分室の居室を予定しております。また、並行して、区内宿泊施設の居室を確保しての実施について調整に臨んでおります。\n４、補正予算額につきましては、申し上げたとおり５４０万円でして、内訳は記載のとおりでございます。なおこちらは、東京都の養育困難児童の受け入れ体制整備事業補助金の申請を予定しております。保護者が安心して療養に専念できる環境を整備することで、子育て家庭に対する新型コロナウイルス感染症への対策を強化したいと考えております。\n説明は以上でございます。ご審議のほどよろしくお願いいたします。"},{"i":158,"speaker":"あくつ委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑等がございましたらご発言願います。"},{"i":159,"speaker":"吉田委員","text":"この、新型コロナウイルス感染症に係る養育困難児童の支援事業というのは大変重要な事業だというふうに思っているのです。それで、実施予定場所が今は、ファミーユ西品川子ども未来部分室は確定というかそれが使えるということで、そこでどれぐらいのお子さんが預かれるのか。それから、区内、今、調整中というのはどれぐらいを想定して調整しておられるのか、確認をさせてください。"},{"i":160,"speaker":"山下子ども家庭支援センター長","text":"本事業の実施に当たる利用人数といいますか、対象をどういうふうに捉えているかというところでございます。\nまず、ファミーユ西品川につきましては、お部屋のほうは２つ、今現在あるのですけれども、利用といいますか準備を進めていくのは今、１室で考えております。広さとしては５０m2ほどあるのですけれども、やはり中で区分け等ができませんので、お預かりできる人数としましてはお一人ないし、ご兄弟等がいた場合には１世帯分のお子さんという形になろうかと想定しております。\nまた、宿泊施設の利用につきましては、その時点での宿泊施設のほうでの居室の空き状況等々によるところですけれども、あまり複数のお部屋を同時に確保できるとは考えておりませんで、１室ないし多くても２室ぐらいが限度ではないかというふうに捉えているところでございます。"},{"i":161,"speaker":"吉田委員","text":"区内宿泊施設、複数は難しいというのはもう、そのとおりなのですが、では今、調整しているのはどれくらいの施設、事業者、まだ、やりましょうというお返事をいただいていないところとかもあると思うのですけども、今、区としてはどれくらいの規模を目指して調整に入っておられるのか、その辺伺いたいと思います。"},{"i":162,"speaker":"山下子ども家庭支援センター長","text":"調整に当たっている宿泊事業者の数というところでございますけれども、今現状、直接に調整に当たっているのは１の事業者であります。こちらにつきましては、当該事業者自体も宿泊施設を運営しているのですけれども、実際に、地元のまちづくりの中で、いろいろな近隣の宿泊施設事業者と連携して対応しているところがございまして、実際にお借りできることになる場合については、複数の事業者のお部屋の確保に至れる可能性も残してはございます。"},{"i":163,"speaker":"吉田委員","text":"分かりました。それで、それだけのことを想定してこの金額ですよね、５４０万円。委託等の経費が主になると思うのですけども、設置準備等経費というのは例えばどんな準備が必要で、この金額で賄えるのかなとかと思うのですけど、その辺の金額についても教えていただけますか。"},{"i":164,"speaker":"山下子ども家庭支援センター長","text":"今回お出しさせていただいている補正額についてでございます。設置準備等経費といいますのは、こちらファミーユ西品川子ども未来部分室における準備の経費として考えております。実際上は、今まで事務室として用いているところから、いわゆる居所といいますか、住むための環境としてのお部屋のしつらえになっておりませんので、少し具体に申しますと、例えば冷蔵庫だとか、そういった電化製品、家電製品の類いの物について準備を進め、実際にそちらを泊まれる環境として整えていきたいというふうに思ってございます。\nまた、支援委託の経費につきましては、一定、幼い方であったりしますと、保育サービス事業者への委託の支援員に対する時給的なところが、かなり長い時間帯にわたることを想定しておりまして、そちらのほうから算出した金額として、現状この金額で補正予算を提出させていただいたところでございます。"},{"i":165,"speaker":"あくつ委員長","text":"ほかにございますでしょうか。"},{"i":166,"speaker":"安藤委員","text":"重要な、大事な事業だと思うのですけど、この間実際にこういう事業が必要とされるような相談というのですか、この間に様々大変な波を経験したわけですけど、区民から寄せられていたということはあったのかというのを伺いたいと思います。\nそれと、こちら実際何歳ぐらいからの利用を想定しているのか。あと、事業の開始というのはいつぐらいからを目指しているのか。それと、夜間などの支援業務というのはどのようなことが行われるのかなどについて伺いたいと思います。\nあと、利用対象者の居所、これは場所としては、罹患した保護者が違う所に移って、そこでお子さんを預かるということも想定しているという理解でよろしいのか、などについて伺います。"},{"i":167,"speaker":"山下子ども家庭支援センター長","text":"何点かご質問を頂戴しました。\nまず１点目の、区民から直接にこういった事業の要望等があったのかというところでございますけれども、直接に区民の方からいただいたというところではございません。他方で先般の第５波のときには、やはり相当程度医療機関が逼迫しまして、そういった状況はあったのではないかというふうに捉えているところと、あと保健所のほうから、こういった支援の体制があると、やはり保健所業務のほうに対してもいい影響を与えるのではないかということでお話をいただいているところでございます。\n続きまして、対象年齢についてですけれども、対象の児童ということでいいますと、やはり若いといいますか幼いお子さんからというところの想定にはなるのですが、ただ実態として、実際にお預かりができる、こちらのほうで安心安全に保護ができるという形になりますと、やはり、就学年齢以降のところが主の対象になってくるかなというふうには捉えております。しかしながら、当然その状況によって、未就学のお子さんがこの支援事業を必要とされる可能性もございますので、その際は保育サービス事業者ないし宿泊事業者と調整に臨んでいきたいと考えております。\n３点目の事業の開始時期につきましてですけれども、本補正予算のほうをご議決いただいた後、早急に要綱等の策定および契約に至れるように、鋭意今、準備を進めているところでございます。\n４点目の、夜間帯のケアというところですけれども、一定その就学年齢に達していましたり、また、それも後段のほうで、自分のことは自分でできるような年齢であれば、電話をかける、そういったことでの確認でも足りるかなというふうに捉えておりますけれども、入学したてであったり、まだ幼いようなお子さんにつきましては、行って直接現場での支援に当たりながら様子を観察する必要があるかなというふうに捉えておりまして、その辺りは臨機応変に対応していきたいと考えております。\nあと、最後の場所についてですけれども、こちらの想定としましては、保護者の方がご入院をされましたり、いわゆる宿泊療養施設のほうに入所といいますか入られたときには、お子さんがご自宅に残る可能性がございます。ご自宅で支援を受けられるというような形での調整が整えば、こちらのほうで支援員をご自宅への派遣という形で捉えておりまして、逆に、入院や宿泊療養施設の利用がかなわなかった場合には、陽性者である保護者の方がご自宅にいらっしゃる可能性がございまして、そういった中で、お子さんのほうが心配であるというようなお声に応じていくのであれば、別途施設を用意して、そちらでお預かりできないかということで調整に当たっているところでございます。"},{"i":168,"speaker":"安藤委員","text":"ありがとうございます。やはり直接はなかったものの、そういう状況があったというのは、今のご答弁からは随分と推測されます。実際あったと思いますし、保健所からもそういった事業があるといいということを言われていたということでした。\n同様の事業というのを先行して行っている自治体というのは、２３区でどれくらいあるのか分かれば、先行自治体の実際の利用状況など、もしこれも分かれば伺いたいと思います。\nあと最後に、宿泊事業者と調整ということなのですけど、子どもの預かりという意味ではかなり専門性も必要なのかなと思うのですけど、そこら辺について不安はないのかというのは伺いたいと思います。"},{"i":169,"speaker":"山下子ども家庭支援センター長","text":"まず、先行区等の状況についてでございます。直近のものではございませんので現在時点ということで必ずしも正しくないかもしれないのですが、私のほうで把握している区としましては、７区ほどがこちらの支援事業のほうの準備ないし体制を整えているというふうに聞いてございます。\n他方で、最も近隣でご照会をいろいろさせていただいた目黒区においては、実際利用にはつながっていないということで実績は、そのお伺いした段階ではなかったというような状況がございます。\n２点目の宿泊事業者における子どもの預かりについてですけれども、今、委員ご指摘のあったとおり、もともと宿泊事業者は子どもを預かる事業を行っているわけではございませんので、そういったところには、宿泊事業と併せてこういったサービス事業者の派遣を含めるなど、支援の体制については安全第一で考えてまいりたいと思っております。"},{"i":170,"speaker":"あくつ委員長","text":"ほかにございますか。"},{"i":171,"speaker":"つる委員","text":"今の安藤委員の質疑のところで、最初に確認なのですが、２の利用対象者の（１）で、入院または宿泊施設での療養を要するというふうにはなってはいるのですが、今の質疑だと親の方がそういうところに入れなくて、自宅にいても、それについての検討というご答弁だったかと思うのです。そこだけ１点まず確認させてください。明確にどちらなのだろうという、入院施設がなくてやむを得ず自宅になっている場合でも、この対象になるのかどうかを確認させてください。"},{"i":172,"speaker":"山下子ども家庭支援センター長","text":"２、利用対象者の（１）の要件についてでございます。こちらとしましては今、委員ご指摘のとおり、本来は療養を要するのだけれども、医療機関ないし宿泊療養施設のほうも含めて、逼迫してしまって利用がかなわないといったような状況については、こちらの療養困難、療養を要しているというふうに捉えていきたいと考えております。"},{"i":173,"speaker":"つる委員","text":"ありがとうございます。大前提で、そういう感染拡大などが本当に終息、終わるほうも含めてですけれども、なっていくということが当然いいわけです。ただ、こういう用意があるということで、近隣区の実績がないというのはそれはそれで、そこまで大事に至っていないという意味で、いいことだと思います。ただ、体制をしっかり整えていくというところが大事な取組かなと。\nもう一つ、保育サービス事業者という形になっているのですが、ここは先ほどのお話だと、未就学の場合は今現在、ちょっと記憶があれなのですけど、病院のところでの対応ということなどもあったかなと思うのですけれども、就学年齢以降が基本線かなというところも含めて、そうすると具体的にどういう資格を持っている事業者になるのかというところと、体制としては、親の方が完全に回復されて戻ってくるまでという時間軸だと思うのですけれど、２４時間交代でどなたかの事業者が、当然その自宅だったらいいのだけども、どこからか遠い所から来て西品川というケースだとか、お子さんは当然陰性という前提があるので、学校に通ったり、園とかあると思うのですが、親がなっている場合は、そのそもそもの前提のところ、ちょっとその辺の確認。\nそれと、そのサービス事業者がどういう事業者なのかというのを教えてください。"},{"i":174,"speaker":"山下子ども家庭支援センター長","text":"１点目の保育サービス事業者というところですけれども、いわゆるベビーシッターの事業者等々につきましては、どちらのところもいわゆる濃厚接触者に対するサービス提供はなかなか行い難いということで、受入れといいますか、連携を図るのが難しいというふうに捉えておりまして、このたび、今いろいろなところを探し当てる中で、区内のＮＰＯ法人に少し話をさせていただきまして、濃厚接触者に当たるような児童についても支援ができないかということで、少々相談を進めたところでございます。\n実体上、今、委員ご指摘あった２４時間体制というのを組むのがなかなかやはり難しいというようなところから、そういったＮＰＯ法人のほうに加盟する前段としましては、いわゆる昔の家政婦というような方が、今、家政士と申しまして、なりわいとして行っているところがございまして、児童・幼児のほうの見守りであったりとか、日頃の生活支援に当たる部分を包含して行っている資格としてやっていらっしゃるということなので、そういったところとの連携を今現在考えているところでございます。"},{"i":175,"speaker":"つる委員","text":"すみません、ちょっと私も前提が今、うろ覚えになってしまって申し訳ないです。そうすると、ここから、というのは西品川だった場合などから、就学の児童だった場合はここから学校に、親と濃厚接触で陰性でも親が陽性だと駄目ですよね。駄目であれば、そこから学校、これはちょっと所管が違うのだけど、教育委員会のほうでタブレットとかを使っての学習とかそういうことを、登園だとか登校は親がこういう状況だと当然これはできないという前提ですよね。\nそれから、そういう部分と、やはり夜間のところというのですか、親がそういう状況で多分通常の、トワイライトステイとかショートステイとかという感覚と、またちょっと違う不安がお子さんにはあるという中で、ただ担い手も当然濃厚接触者の家族の子どもに対する対応というところは非常に悩ましい部分だと思うのですが、その辺のケアというのは、手を挙げていただいている事業者を含めて、どういう想定があり、どういうことが可能なのかというところを教えてください。"},{"i":176,"speaker":"山下子ども家庭支援センター長","text":"いわゆる保育サービス事業者のほうにおきます支援につきましては、その支援に当たる人材のほうがかなり逼迫しているということは、現場のほうの声として聞いておりまして、どこまでできるかというのが、そのケース・バイ・ケースの部分がどうしても出てこようかと捉えております。\nそういった中で、実際宿泊事業者のほうにおきましては、かえって宿泊拠点として営業している関係で、いわゆる大人の方がいらっしゃることが想定されますので、当初、そちらのほうの施設に支援員の方たちに来ていただくスキームを念頭に置いて想定をしつつ、宿泊事業者のほうについても、後からどこかできるところはないかというふうに検討に当たったところでございます。\n宿泊事業者のほうにつきましては、その子どもの預かりという面におきまして、当然その専門家ということではないのですけれども、一定夜間帯見守りが必要なお子さんであっても、例えば階下に職員の方がいるというような形は担保できるかと捉えておりますので、そちらのほうで準備が進められるように努めてまいりたいと考えてございます。"},{"i":177,"speaker":"つる委員","text":"実際はそういうソフト的な対応というのは、本当に他区とか先行している７区で実際に事例があったところとかでないと当然参考にならないかと思うのですけど、いろいろ、工夫しているところを品川区もぜひ、そういう際に参考にしていただきたいなというところ。\nあと最後がお金のところで、今回その支援委託等というところに入ってくると思うのですけど、４７５万２,０００円というところで、これはアイドリングといいましょうか、その事業者が、要するに発生した段階でそういうやり取り、金銭の発生になるのか。それとも、やはりいつそうなるか分からないので、もう期間設定で、これ年度内の金額かなとは思うのですけれども、そこの辺りがどういうような話になるのかなと。宿泊施設も確保しているとなると、やはり居室確保でずっと支援が必要な子どもがいないのだけれども支払い続けるという、そういう仕組みなのか、それとも発生した段階で探してというところだったのでしたか、この宿泊施設のほうは。だからその辺のお金がどのように使われていくのかというところを教えてください。"},{"i":178,"speaker":"山下子ども家庭支援センター長","text":"補正予算額における契約の形態といいますか想定というところでございます。今考えておりますのは、まず、この仕組みを構築していくに当たっての準備的な経費につきましては一定お支払いをし、あと、実際に支援が必要になった場合にその支援の経費についてお支払いをしていくというような二段構えで考えております。\n今、委員のお話にございました、いわゆる居室の確保につきましては、空室のところにお金を充てていくような形は今のところ考えておりませんで、実際にこの利用の想定が出てきた場合に、その時点で居室の確保に努めてまいりたいと考えてございます。"},{"i":179,"speaker":"つる委員","text":"ありがとうございました。では先ほど、吉田委員のときに、事業者の時給とありましたけれども、そうすると人員の確保というところでのそこは、発生したときに出動した段階でかかるという、今いただいたご答弁で理解しました。ありがとうございます。"},{"i":180,"speaker":"あくつ委員長","text":"ほかにございますでしょうか。\nほかにご発言がないようですので、これで質疑を終了いたします。\n採決に入ります前に、本件につきまして、各会派の態度を確認いたします。\nそれでは、品川区議会自民党からお願いいたします。"},{"i":181,"speaker":"松澤委員","text":"賛成です。"},{"i":182,"speaker":"つる委員","text":"賛成です。"},{"i":183,"speaker":"安藤委員","text":"これも、コロナ感染を防ぎ、保護者の負担を減らすことに資する事業なので、賛成です。"},{"i":184,"speaker":"吉田委員","text":"必要な事業だと思います。この予算額が、これでどうなのだろうかというのはさっきあったのですけど、今の質疑の中で確認できましたので、賛成いたします。"},{"i":185,"speaker":"松本委員","text":"賛成です。"},{"i":186,"speaker":"あくつ委員長","text":"それでは、これより第６４号議案、令和３年度品川区一般会計補正予算（歳出 文教委員会所管分）について採決いたします。\nお諮りいたします。本案は、原案のとおり決定することにご異議ありませんか。\n〔「異議なし」と呼ぶ者あり〕"},{"i":187,"speaker":"あくつ委員長","text":"ご異議なしと認めます。よって本案は、全会一致で原案のとおり可決決定いたしました。\n以上で、本件および議案審査を終了いたします。\n────────────────────────────────────────────\n２ 請願・陳情審査\n(1)令和３年請願第１１号 品川区私立幼稚園保護者負担教育費の軽減に関する請願"},{"i":188,"speaker":"あくつ委員長","text":"次に、予定表２の請願・陳情審査を改めて行います。\n初めに、(1)令和３年請願第１１号、品川区私立幼稚園保護者負担教育費の軽減に関する請願を議題に供します。\n本件は、初めての審査でありますので、書記に朗読させます。\n〔書記朗読〕"},{"i":189,"speaker":"あくつ委員長","text":"朗読が終わりました。\nそれでは、本件に関しまして、理事者よりご説明願います。"},{"i":190,"speaker":"若生保育支援課長","text":"私から本請願についてご説明いたします。\nまず、入園料補助金ですが、過去数回の増額を経て、現在１０万円を私立幼稚園に入園した方に補助をしているところです。\n次に、私立幼稚園の振興のための直接助成金につきましては、幼児教育・保育の無償化に伴う事務負担増を考慮しまして、令和２年度から運営費補助を１園当たり１００万円増額し、２２０万円としました。\nまた、運営費のほか、教材費、研修費、健康管理増進費、心身障害児教育事業費、防災安全対策費、インフルエンザ予防接種費、衛生管理費のそれぞれについて補助を行ってございます。\n次に、請願を出された団体への助成ですが、私立幼稚園協会に対しまして、毎年５５０万円の補助をしておりまして、そのうち請願を出された団体が実施される研修や講演会等において、会場費や講演料などに充てられてございます。\nこれまでも適宜、助成額の増額やメニューの拡充に努めてまいりましたが、今後も私立幼稚園を取り巻く状況の変化を見極めつつ、保護者負担の軽減と幼児教育の充実を図るため、必要な支援を行ってまいります。"},{"i":191,"speaker":"あくつ委員長","text":"説明が終わりました。\nこれより質疑を行います。ご質疑等がございましたら、ご発言願います。"},{"i":192,"speaker":"つる委員","text":"まずこれ、請願要旨に１、２とありますが、１のほうの入園料補助金の現在の補助金額なのですが、請願の理由の文章の中の、平成２１年度には入園料補助金を増額していただきましたというふうに記載があって、現在は補助金の金額は１人当たり１０万円かというふうに理解していますが、この１０万円になったときというのがこの平成２１年度からでしょうか。今現在の１０万円になったときがいつからかというのをまず教えてください。"},{"i":193,"speaker":"若生保育支援課長","text":"入園料補助金に関しましては、こちらの請願の文章上では平成１９年度と平成２１年度に増額というふうに記載されてございます。\n一方、私どものほうでの増額のタイミングの記録としましては、平成１８年の４月に、当時８万５,０００円に増額しました。その後、その翌年の平成１９年４月、こちらで１０万円に増額したということで、それ以降は１０万円ということで変わらずという状況でございます。ですので、平成１９年４月に最後の増額、１万５,０００円を増額したというところでございます。"},{"i":194,"speaker":"つる委員","text":"この記載、記録がちょっと若干あれ、というところが、それはそれとして、そうすると、いろいろなその年度年度、また前後して、いろいろな考え方でこの支援をずっと続けていただいているところなのですが、そうすると、平成１９年からですから、２００７年だから十三、四年、上げていただいて経っています。１０万円になってから１４年。\nただ、平成１８年から平成１９年のこの１年間でどんとこう大きく１０万円になったというのは、当時はその分母がどうだったのかなと。昨年の質疑の中での入園料の平均が１３万５,０００円ぐらいですというご答弁があって、それに対する今、１０万円ということなのですが、ただ当時の平成１８年度から平成１９年度のときの入園料のアベレージがどのぐらいだったのかなというのは、これは当然あるわけですけれど、またこの十数年、この間、入園料の補助金については、この理由の中で平成３０年度となっていますが、そのときに所得制限を撤廃いただいたりということがあるわけですけれども、この補助金のさらなる増額という、この請願の要旨に記載されています、この辺の当時の平成１８年から平成１９年のときの増額した理由といいましょうか、背景も含めてということと、この間十数年たっています。それで、入園料の平均が昨年の答弁では１３万５,０００円とあるわけですけれども、この辺りの今の品川区の考え方を教えてください。"},{"i":195,"speaker":"若生保育支援課長","text":"入園料の補助金に関しましての、平成１９年度に１０万円にした当時の状況でございますが、当時、園のほうでの入園料の平均というところでは、申し訳ございません、資料を持ち合わせておりません。\nただ、平成１９年度あたりの状況でございますと、保育園のほうの入園者数というのも増えてきている部分もございますし、そういったところで公私の格差というところを一定程度縮めていかなければならないという、そういう時代背景も一方であったのだろうと推察されるところではあるのですけれども、そういったことで１年間でこういった増額があったというところは、推測になってしまうのですけれども、捉えているところでございます。\n今後、この入園料の取扱等の、保育料も含めてのところでございますけれども、私立幼稚園のほうも、現在の状況では、入園者数が年々徐々に減っている部分もございまして、一方で保育料ですとか入園料で若干の値上げというところも、園の中では行われているところでございます。\n一定程度、そこまで全園が上げているわけでもございませんし、上げ幅というのもそこまで大きいものでもございませんので、そういったところの状況も区は把握してございますので、徐々にそういったところの状況、それから保護者負担のところと見比べて、どのくらいのレベルが適切なのだろうかというところは、それは社会情勢等も含めまして、今後も区のほうでも把握しつつ、必要に応じて増額というところも検討していきたいというふうに考えてございます。"},{"i":196,"speaker":"つる委員","text":"細かい部分については、この請願が今日の採決でどうなるかですけど、今、最後答弁あったところは一つ大きいかなと思いました。ただ、一方でどちらのベクトルかというところはあると思うのですが、いわゆる保育園関係、それから幼稚園関係、国のほうでいろいろな、こども庁ないしこども家庭庁等の、そういう機関的な部分は少し前になっていろいろ精査しなければいけないということで出てきていますけれども、これは、私立の幼稚園側からのそういうベクトルというのでしょうか、子どもを守り支える場所としての部分だとは思うのですが、そういったことも含めていくと、この辺の補助金の在り方というのが、いい意味で保育園に預けているご家庭と幼稚園のご家庭ではやはり、差というか、当然、そこで提供されるものもそれぞれのことで、特に私立ですからいろいろあるわけですけれど、そういう役割というか立ち位置というところについては、保護者に対する支援というところでは、最後ご答弁いただいたことは非常にいいかなと思います。ただ、全体観に立って、必要な支援を今後、園ないし通われる園児、そしてそれを家庭で守っていただいている保護者の方にも通じるような、そういう幅広な支援を今後もお願いしたいというふうに、現状は確認できました。"},{"i":197,"speaker":"あくつ委員長","text":"ほかにございますでしょうか。"},{"i":198,"speaker":"松澤委員","text":"今、お話を聞いていまして、私立幼稚園の人数が減っているといったご答弁がありましたけれど、そういった下げ幅、人が減ってきた、そういう現場の状況、その理由というのは、品川区としてはどれくらい具体的に、どういう感じでという、そういう把握というのはあるのでしょうか。教えてください。"},{"i":199,"speaker":"若生保育支援課長","text":"私立幼稚園に関しての、入園者数が若干減っている理由の把握でございます。区としましても、実際毎年度、入園者数は統計で取っているところでして、ここ数年、特に二、三年の部分で、過去しばらく横ばいできたところが若干減ってきているというふうに把握してございます。\n理由としましては、いろいろな要素が考えられて、これというところが今のところ、はっきりと言えないところではございますが、一つ、明らかにその状況が変わっている部分としましては、やはり私立保育園の開設数が、ここ数年、かなり増えているというところと、女性の方の就業率が上がってきているというところから、一定程度保育園のほうが受皿になっている部分があるのかなと。ただ、私立幼稚園に関しても預かり保育等々もやっていただいていますし、いろいろそれぞれご努力いただいておりますので、ほかにも、やはり区立の幼稚園の状況ですとかもございますし、様々、その辺の状況については区としても、この分析を続けていきたいというふうに考えてございます。"},{"i":200,"speaker":"松澤委員","text":"ありがとうございます。今まで数々、年度ごとに補助金の増設であったり所得制限の撤廃とかいろいろ努力していただいているのは分かりました。その中で、私立幼稚園協会などと品川区が直接お話するというのは、多分、各園同士ではないと思うのです。そうすると、私立幼稚園協会の中で代表の方とお話をして、その私立幼稚園の情報というのは品川区が共有するのか、それとも、一園一園というわけではないですけど、そういうのが、一園一園私立幼稚園と話合いをされるのか、その辺はどういうことなのでしょうか。"},{"i":201,"speaker":"若生保育支援課長","text":"私立幼稚園の各園の皆さん、あるいはその協会との連携といったところでございます。所管課としましては、まず私立幼稚園の全体的な部分に関しましては、やはり私立幼稚園協会の会長ですとか、あるいは事務担当の方を通じて、日々お話しさせていただいたり、あるいは毎月園長会を協会で行っていますので、私どもが随時参加させていただいたりというところで、情報の連絡ですとか共有というところを図っているところでございます。\nそれとは別に、日々、私どもの幼稚園担当のほうから各園に、メールですとかあるいは電話等々でやり取りさせていただいてございますので、そういった園の情報というのは、あまりその運営の中身まで園に行ってというところはなかなか機会があまり取れないところではございますけれども、電話ですとかメール、あるいは園の方が直接いらっしゃってご相談ということもございますので、そういった連携というか情報の共有、それからご相談等も行っているところでございます。"},{"i":202,"speaker":"あくつ委員長","text":"ほかにございますでしょうか。"},{"i":203,"speaker":"安藤委員","text":"今回請願を出された団体ですけど、区が把握するところでいいのですが、具体的にどういう活動をどれくらいされているのかということを教えていただきたい。\nあと、区としてはそういう活動というのをどのように評価されているかについても伺います。"},{"i":204,"speaker":"若生保育支援課長","text":"今回請願を出された団体の活動内容につきまして、実際、直接やり取りするというところは、こちらの請願のタイミング以外はなかなかない部分ではございます。ただ、先ほどご説明で申し上げたとおり、協会への補助金の５５０万円の実績報告の内訳の一部に、今回請願を出された団体の活動、いわゆる研修ですとか、あるいは講演会ですとか、大会のほうの運営にかかる費用ですとか、そういったところに充てられているということを把握してございますので、各幼稚園の活動、こういったところを、保護者ですとか教員の立場から、いわゆる学校でいうＰＴＡと同様のような取組になるとは思うのですけれども、教育の下支えというところで貢献していただいていると区では認識してございます。"},{"i":205,"speaker":"吉田委員","text":"いろいろ、質疑の中で、やはり女性の就労が増えたという中で、なかなか私立幼稚園の運営というところで、人数が減ったりとかいうようなことは理解できました。基本やはり、ライフスタイルだってそれぞれ、どのようなライフスタイルを選ぶかは皆さんの自由ですし、選ぶときもやはり特色のある私立幼稚園の教育を選びたいという方もおられると思うので、品川区としてもそこに補助というのは必要だというふうに思っております。\nそれで、私、補助金の出し方がよく理解できていないのですけど、結局保護者のほうの負担軽減に直接つながるものと、それから幼稚園の運営に資するための補助金というふうに、両方進んでいると思うのです。それで、今私たち、常に私立保育園の補助金の使い方について、品川区が適正に使われているかを点検してほしいということをいつも求めておりますので、その関連で言うと、こちらについてもご説明をしていただきたいところが１個あります。\n私が調べてくればよかったのですけど、心身障害児教育事業費補助金について、これは心身障害児を受け入れるために必要な補助金として充てられていると思うのですけども、これも各園にそれぞれ、現実、受け入れているとか受け入れていないということも関係なくあるのか、それとも１人受け入れるごとにこういう補助金が出るということなのか、すみません、その辺の仕組み、基本的なところを伺って申し訳ないのですけど教えていただきたいと思います。"},{"i":206,"speaker":"若生保育支援課長","text":"私立幼稚園の補助金の、いわゆる園への直接補助金の使い道というところの確認でございますが、こちらについては、区として必ずその事業実施の計画書ですとか、あるいはその見込みのところを出していただいて、それに対して補助金を支給して、実施した後にこちらの実績報告という形で必ず一定の様式の書類を提出していただいて、そこで区のほうでもチェックをかけているということでございます。\nなかなか、その個々の補助金に対して実地でというところは行けていないところではあるのですけれども、今後私立幼稚園に関しても無償化が入ってございますので、そういった面で一定程度、公的な国ですとか都からも財源が入っているというところもございますので、そういった意味でチェックというのは今後、改めて検討して実施していこうというふうに考えているところではございます。\nそれから心身障害児の補助金でございます。こちらについては、心身障害児、障害があるお子さんが園へ入園された場合に、１人当たり３０万円を園に対して、こちらは人件費相当分という意味合いもございますし、園の設備的な部分での補助というところにも使えるような形で、園に対して支給しているものでございます。"},{"i":207,"speaker":"吉田委員","text":"分かりました。本当に下調べが悪くて申し訳ありません。たしか、予算特別委員会だったか決算特別委員会だったか、どなたかのご質問の中で、この補助金が出ているのに受け入れてもらえていない実態があるというようなことがあって、そのご答弁がどうだったか全然覚えてなくて、調べていなくて申し訳ないのですけど、本来だったらそういうことはないはずということですよね。この補助金は、例えば受け入れるから申請するということで報告が出ているというふうに理解してよろしいのでしょうか。ちょっと確認させてください。"},{"i":208,"speaker":"若生保育支援課長","text":"心身障害児教育事業費の補助金は、あくまでも障害がある方が入園された後に申請いただくことになりますので、実際支給しているのにそういったお子さんがいらっしゃらないという状況はないというふうに認識しております。"},{"i":209,"speaker":"あくつ委員長","text":"ほかはよろしいでしょうか。\nほかにご発言がないようですので、これで質疑を終了いたします。\nそれではまず、令和３年請願第１１号の取扱いについて、ご意見を伺いたいと思います。\n継続にする、あるいは結論を出す、どちらかご発言願います。また、結論を出すのであれば、その結論についてもご発言ください。\nそれでは、品川区議会自民党からお願いいたします。"},{"i":210,"speaker":"松澤委員","text":"本日結論を出すで、採択でお願いいたします。"},{"i":211,"speaker":"つる委員","text":"本日結論を出すで、採択でお願いいたします。\n理由は先ほどの質疑のとおりです。"},{"i":212,"speaker":"安藤委員","text":"本日結論を出すで、採択です。\n全ての幼児教育・保育の無償化を進めていくことは重要だと思いますので、採択を主張いたします。"},{"i":213,"speaker":"吉田委員","text":"本日結論を出すで、採択を主張いたします。\nただ、やはり補助金に関しては、今、ご答弁で確認できましたけれども、やはりそれがきちんと保護者なり保育者、それから幼稚園教諭、それから幼稚園の運営にきちんとその補助金が目的どおり使われているかの確認は、ぜひ進めていただくということを前提に、採択を主張したいと思います。"},{"i":214,"speaker":"松本委員","text":"本日結論を出すで、採択でお願いします。"},{"i":215,"speaker":"あくつ委員長","text":"それでは本請願につきましては、結論を出すとのご意見でまとまったようでございますので、そのような取扱いでよろしいでしょうか。\n〔「異議なし」と呼ぶ者あり〕"},{"i":216,"speaker":"あくつ委員長","text":"それでは、本件は結論を出すことに決定いたしました。\n先ほどそれぞれの方のご意見を伺いましたので、本請願につきましては、簡易採決により採決を行います。\nそれでは、令和３年請願第１１号、品川区私立幼稚園保護者負担教育費の軽減に関する請願についてお諮りいたします。\n本件を採択とすることにご異議ありませんか。\n〔「異議なし」と呼ぶ者あり〕"},{"i":217,"speaker":"あくつ委員長","text":"ご異議なしと認めます。よって、本件は採択と決定いたしました。\n以上で本件を終了いたします。\n────────────────────────────────────────────\n(3)令和３年陳情第５３号 新型コロナウイルス感染症に関する要望についての陳情"},{"i":218,"speaker":"あくつ委員長","text":"次に、(3)令和３年陳情第５３号、新型コロナウイルス感染症に関する要望についての陳情を議題に供します。\n本陳情は初めての審査でありますので、書記に朗読させます。\n〔書記朗読〕"},{"i":219,"speaker":"あくつ委員長","text":"朗読が終わりました。\nそれでは、本件に関しまして、理事者よりご説明願います。"},{"i":220,"speaker":"若生保育支援課長","text":"私から、本陳情について説明させていただきます。\nまず、１、保育施設関係者へのＰＣＲ検査の実施ですが、区では、コロナ陽性患者がいた場合、症状の有無に関わらず、濃厚接触者に対しては迅速にＰＣＲ検査を実施し、感染者の早期発見等に努めております。\n定期的な検査や無症状の希望者全員への検査については、その検査間隔も含めて実施の意義について結論が出ていないため、実施の予定はございません。\n２、医療補助などに関しまして、区では、昨年度に引き続き、感染症拡大防止等に必要な物品の購入等に係る費用の補助を、区内私立保育園等に対して実施しています。今後も感染状況を注視し、必要に応じて効果的な支援策を講じてまいります。\n３、ワクチン接種に当たっては、区の集団接種会場において、通常の接種希望者に接種するワクチンの余り分を保育事業者に対して優先的に配分するよう取り組んでまいりました。また、都が設置するワクチン大規模接種会場においても、保育所等職員を対象とした接種が行われており、周知に努めてきたところです。また、副反応による職員の労務管理上の対応については、各設置者において適切に行われるものと考えます。ワクチン接種に関し、園で不適切な対応が見られた場合には、区から園や設置者へ指導をしております。\n４、感染拡大防止の観点から、区が保護者へ登園自粛要請を行った場合は、その期間に応じて保育料を日割り計算しております。延長保育料については、私立保育園では各園の判断で月ぎめとしている場合もありますが、保護者の申出により日払いへの変更なども柔軟に行われているものと認識しております。\n５、感染拡大防止に有益な情報提供について、区では、適宜、公・私立それぞれの保育園長会等で、コロナ感染症に関する事例の共有や注意喚起などを行ってきました。今後も感染拡大状況に即し効果的な情報提供を行ってまいります。\n６、国、東京都に対しては、区として、特別区長会等を通じて、新型コロナウイルス感染症対策を含む施策および予算に関する要望を行っているところであり、引き続き様々な機会を捉えて国や都へ声を上げてまいります。"},{"i":221,"speaker":"あくつ委員長","text":"説明が終わりました。\nこれより質疑を行います。ご質疑等がございましたらご発言願います。"},{"i":222,"speaker":"安藤委員","text":"改めて、保育園現場での感染状況について伺いたいのですが、今年度に入って、これまで、子どもと保育士、それぞれの区内の感染者数を教えてください。あと、クラスターが発生した保育園数も伺います。\nまた、いわゆる第５波が落ち着いて以降の感染状況の変化というのはどうなっているのかというのも併せて伺いたいと思います。\nそれと併せて、これは認識をお伺いしたいのですけど、保育の現場というのはやはりマスク着用が難しい乳幼児も保育されておりますし、また、学校に比べても遊びですとか保育者とのスキンシップを通して学んだり成長する場であるという特性上、やはりなかなか感染拡大防止が困難な条件がある施設、現場だと思うのですけど、区としてはそのような認識というのはおありでしょうか。伺いたいと思います。"},{"i":223,"speaker":"初貝保育教育運営担当課長","text":"幾つかご質問をいただきました。\nまず、公立の保育園におきましての本年度に入りましての感染状況でございますけれども、１０月末までの累計でございます。園児が、陽性が出たのが７９名、職員に関しては４８名というようなところでございます。それとあと、クラスターの発生というところに関しましては、我々、クラスターというような名称を使ってございませんけれども、公立に関してはそういった大量に、一度にというようなところまでは発生してないという状況でございます。\n続いて、第５波が落ち着いた後に、というようなところでございますけれども、ちなみに今月に入りまして、１１月でございますけれども、園におきましては、職員、園児に関しては感染者が今のところ発生していないというような状況でございます。\n続いて、マスクの着用であったり、そういったところの園児との、コロナが防ぎ切れないような現場ということの捉えに関しましては、マスクができない乳児だったり、そういったお子様をお預かりしているというところでございますけれども、適切な消毒であったり、基本的な対策というところを徹底してまいりまして、コロナの拡大を防ぐというようなところで現場では対応しているところでございます。"},{"i":224,"speaker":"若生保育支援課長","text":"続いて、私立の保育園の状況でございますが、まずは感染者数でございますけれども、今年度、１０月末までのところで申し上げますと、園児に関しては１２６名、それから、職員が１２７名というところでございます。\nまた、クラスターというところでは区立同様、そういった発信の仕方は区として行ってございませんが、かなり大規模に感染状況が生じたというケースは、特に第５波、７月から８月末ぐらいにかけてというところでは、数園生じているというところは認識しているところでございます。\nそれから最近の感染状況でございますが、１１月に入ってからは区立と同様、全く感染者数は出てございません。そういった相談も全く来ておらず、落ち着いている状況でございます。\nそれから、園児等のマスクができないというような状況の中での保育の部分でございます。こちらも先ほどの区立と同様、園の中で可能な限り工夫できる部分で感染対策を引き続き行っていくというのが大事だというふうに考えてございます。"},{"i":225,"speaker":"安藤委員","text":"クラスターのところは把握していないというか、何でそうなのかなというのはちょっと分からないのですけど、なぜ保育部門はそういう把握の仕方をしないのかなというのはちょっと謎なのです。何か理由があれば伺いたいのですけれど。でも、そんなにいっぱいは発生していないということだと思います。\nあとは、私が伺った後段の質問なのですけど、基本対策を徹底していくというのは、それは当然のことなのですが、保育園という事業を進める上では、コロナではタブーとされる接触というのがどうしても避けられない施設なのではないですか。だから、感染拡大防止という点では困難な状況がある現場なのではないでしょうか、そういう認識はあるのでしょうかと聞いたので、それは答えていただきたいなと思います。\nそれと併せて、この陳情の項目の１番の辺りなのですけど、保育従事者への定期的な検査というのは、今まさにオミクロン株という話も出ていますし、今、新規感染者数が落ち着いているときだからこそ、こういう体制を整えておくと。それで必ずその感染の芽のところで摘んでいくという意味で、すごく大事だと思うのです。ですから、この定期的な検査は、私は必要だと思いますが、これまでも拒否をしてきたわけですので、なぜやらないのか、改めて理由を伺いたいというのが２点目です。\n併せて、項目５についても伺ってしまいますけど、感染対策の区の指針、マニュアルというのを含めた情報提供というのは、現場の保育園には一体どのように行われているのか。例えば学校分野ですと、感染防止マニュアルというのを独自につくってバージョン更新して、ホームページもアップしているわけなのですが、特に私立の事業主の方などからよく聞くのはほとんど、そういう対策指針みたいなものが区からはないです、みたいな話を聞くのです。ですから、その辺についてどうなっているのか、区立園、私立園それぞれについて伺いたいと思います。"},{"i":226,"speaker":"初貝保育教育運営担当課長","text":"幾つかご質問をいただきました。\nまず、接触が避けられない現場ということで、我々のほうも保育士の愛情を子どもたちに伝えるというようなところで、やはり接触というところはある程度避けられないというような状況は捉えております。ただ、コロナ下でも、保育士間の感染がまずないようにするであったり、あとはお子様たちと接した後や定期的に小まめな消毒を保育士が行うであったり、または環境のところで、例えば遊びの中でも、それぞれ集団を分けたりというような工夫をして、接触をしながらも感染がなるべく低減されるような工夫をしているところでございます。\nそれとあとは、定期的な検査体制のところに関しましては、今までも保健所のほうと連携をしながら、適切な体制で必要に応じて検査をし、対応しているところでございます。\n続いて、あと、情報提供のところに関しましては、保育園のほうには、例えば園長会、施設長会などを通じて、あとは適宜公立に関しましては会談を通じてなどで、国のほうから示されている、保育所における感染症対策ガイドラインであったり、あとは保育所等における新型コロナウイルスへの対応にかかるＱ＆Ａというところ、これが頻繁に更新をされているというところでございますけれども、そういったものを伝えて、説明をして、その徹底を図っているというようなところでございます。"},{"i":227,"speaker":"若生保育支援課長","text":"ただいまの答弁の補足ですが、定期的な検査をなぜ実施しないのかということでございますけれども、ＰＣＲ検査につきましては、検査した時点での感染を調べるものでございまして、そこからどのタイミングでどういった頻度でやるのか、定期的にといっても、どのぐらいの間隔でやるのかといったような実施の意義というのはまだ、保健所のほうでのお話でも、そういったところの結論が出てないというところもございます。\nですので、そういったところも含めまして、検査の体制ですとか、そういったところも相当程度影響してくる部分もございますので、区としては、定期的な検査については慎重に考えているところでございます。\nそれから、マニュアル等々を区のほうでの提供というところで、私立保育園関係は特にというお話もございましたけれども、先ほど保育教育運営担当課長が申し上げたとおり、国からＱ＆Ａですとか通知等が頻繁に更新されて発出されているので、それは、すぐに情報提供をさせていただいて、かつ、先ほど申し上げた園長会等で共有を図ったり、注意喚起をしているところでございます。\nむしろ、区で独自に何かというところになりますと、そこはもう個々の園とのやり取り、これを密にやっております。保健所と私どもの保育所管のほうとも、かなり密に連携を取りつつ、感染状況に応じて迅速な対応をしているところでございますので、逆に言えばそういったマニュアルで全て解決できるようなものではなく、適宜状況に応じて対策も変化してくるものでございます。そういったところを随時、迅速に対応しているというところでございます。"},{"i":228,"speaker":"安藤委員","text":"項目５の点については、様々情報提供はしているということですが、実際、受けている現場のほうからすると、やはりそういう感覚がないといいますか、どんどんファクスは来るのでしょうけれど、あとは皆さん、それ見てやってくださいねというふうに、やはり思ってしまうのです。ですから、なかなか独自に教育委員会みたいにマニュアルつくるというのは大変かもしれないのですが、もう少し現場の園が取り組みやすいような工夫といいますか、情報提供の在り方の工夫と充実というのをお願いしたいというふうに思います。\nそれと、この園自体がなかなか大変なのでは、感染対策からいって大変な特性あるのではないかという質問なのですけど、いろいろ工夫していますと、そのとおりだと思います。物すごい工夫と努力でやっているから、やはりもう感染させないように、物すごい気を遣っているわけです。やはりその努力自体が、本当に気を遣わなくてはいけないという保育の事業というところの特性から起因するものでもあるので、ここはしっかり、そういった現場の努力に最後は委ねられるのでしょうけど、しっかり保育行政としてその感染拡大抑止に奮闘している現場を、本当に支援していただきたいなというふうに思います。\nそれと、検査ですけども、もうコロナになってから何年たっているのかということで、その検査の実施の意義すら、時期の意義すら結論出ていないというのは、私はどういうことかと思いますけど、やはりその時点での感染が分かる、その時点の感染しか分からないとよく言いますけど、その時点の感染で、感染しているか、していないかと分かること自体というのが、少なくとも、今この時点で保育園に蔓延しているのかどうかをやはり確認して安心したいという保護者、子どもたちにとってはそれだけでも非常に重要なわけです。\nですから、私は、やはり無症状の陽性者をしっかり早期に把握して保護していくという体制に早く立つためにも、定期的な保育園での保育従事者への検査というのをやってもらいたいですし、それと、感染者が出た場合の検査、それについても、必要な検査をやっていますと言いますけれども、ぜひこの保育課として、現場としても、その保護者とか保育従事者の不安に寄り添って、ここに書いているとおり、陽性者と報告されたときには、狭い施設なわけですから、希望者全員に検査をするようにしていただきたいと思います。\n最後の質問ですが、そこのところでもう１回伺いたいのですけど、今落ち着いていますけど、現在保育園に陽性者が出ましたというときの検査の考え方、改めて現在どうなっているかというのをちょっと確認させてもらいたい。\nそれと、なぜ、その検査を拡大といいますかここに書いているとおり、陽性者が報告されたときに希望者全員にＰＣＲ検査を実施しないのか。もう一度、理由を伺わせていただきたいと思います。"},{"i":229,"speaker":"あくつ委員長","text":"安藤委員、繰り返しになっているように私は聞こえるのですが、ご答弁はいただきますけれども、最初にご説明があったこと、そしてもう一度ご質問されたことに対しての答弁、そして今回またもう一度同じことについて伺っているように聞こえるので、あまり繰り返しにならないようにお願いしたいと思います。ではご答弁お願いします。"},{"i":230,"speaker":"初貝保育教育運営担当課長","text":"今回ご質問いただいた、現在の検査体制の考え方、園でコロナが発生したときの検査体制ですけれども、今月は感染情報ございませんけれども、もし発生した場合には園のほうで濃厚接触者の特定を行います。その濃厚接触者の特定というのは、保健所とも連携をしながら、特定をすると。その後、その特定された方に対して検査を行っていくというような形で、体制が組めるならば集団で、保健所と連携して検査を行うというような形で行っております。その特定された後に、必要に応じて、それぞれの方に自宅待機だったり、そういったところを呼びかけていくというような形になっております。"},{"i":231,"speaker":"安藤委員","text":"今のところ、確認したいのですけど、濃厚接触者と特定されなければ検査はされないということは変わっていないということなのでしょうか。私はそれを確認したいのと、それだけだと保護者の不安も解消されないし、実際に園内に無症状の陽性者を残してしまう、園内にまた感染を蔓延させてしまう危険性を残してしまうのではないかという、この２点、お伺いさせてください。"},{"i":232,"speaker":"初貝保育教育運営担当課長","text":"現在の対応といたしましては、濃厚接触者と特定された方に対してきちんと検査をしていくというようなところで、それ以外の保護者であったり、あとお子様に関しまして、ご不安を抱かれるようなお話がございましたら、区のほうでは、園や保育課も含めて、きちんとご理解がいただけるように説明をして、ご安心していただけるような対応をしているところでございます。"},{"i":233,"speaker":"あくつ委員長","text":"ほかにございますでしょうか。"},{"i":234,"speaker":"吉田委員","text":"先ほどのご答弁でよく分からなかったのですけど、陳情項目の３番目の体調不良時の休暇の保障や職員体制の維持については、補助ではなくてその事業者のほうで行うというご答弁だったのでしょうか。ちょっとそこを聞き取れなかったので、教えていただきたいです。\nそれから、４番目の柔軟な対応、日割り徴収など柔軟な対応については、柔軟に対応しているはずというようなことでしょうか。そこだけもう一回確認させてください。"},{"i":235,"speaker":"若生保育支援課長","text":"ご質問、３の副反応による体調不良時の対応でございます。ワクチンを打った後に、当日ですとか翌日などに休暇を取られた方のシフトの穴埋めというのですか、そういった労務管理については、これは私立でいえば保育事業者、もしくは園長ですとか主任、そういったところで実際のところ対応が行われているところでございますので、ここについて、何らか区として、もちろんそこが不適切な部分が見られた場合には指導等をしているところではございますけれども、そういった職員のシフトですとか管理というようなところになりますので、これは各設置者において適切に行っていただくものですので、そういった考え方を申し上げたというところでございます。\nそれから、４の、これは登園自粛等の際に、保育料ですとか延長保育料の日割り徴収など柔軟な対応というところでございますが、こちらは保育料に関しましては、認可保育園であれば当然、区のほうで保育料を徴収しておりますので、区から登園自粛等を行った場合はその日に応じて日割りでお返しするという対応を行っております。\n延長保育料についても、通常、区立と私立の多くでは、その延長した日の日ごとの日払いというのが通常、行われているのが多いのですけれども、私立の中には、例えば１時間延長しますというのを月ごとで決めて、その月分まとめてお支払いしますというようなやり方をしている保育園もあるものですから、そういったときに、例えば登園自粛で登園できなかった、延長も使わなかったといった場合に、そこが丸々かかってしまうのは、それは不合理ではないかというお話に関しては、そこは日払いに随時変えるような対応を事業者でやっているということは私ども聞いておりますので、そういったところで柔軟に、延長保育料に関しましても柔軟な対応をされているという認識をしているというようなことでお答え申し上げたところです。"},{"i":236,"speaker":"吉田委員","text":"あくまで保育支援課と事業者とのやり取りなので、現実どうかというのはまた、例えば現実に品川区内の保育所で働いている職員とかでも、人員の代わりにこの人を当てるというので休んでくださいというような体制は取られていないというように聞いています。\n私の娘は全然ほかで、保育所ではないのですけど、やはりエッセンシャルワーカーで、だからワクチンは優先接種で、接種した後は休むようにという指示は出るのですけども、その間、では誰かほかの人が、人の手当というところまでは、休みなさいという指示は出るのだけど、ほかの人の手当というところまでは行われないということではほかの自治体も同じような実態、ほかの事業でも同じような実態があるのかなというふうに感じているところです。\nなかなかその事業者のほうがやっているはずということであるけれども、例えばこれ研修のときに、生活者ネットワークとして質問していますけど、いろいろな研修についての補助金などは出てくるのだけれども、その研修に行っている間の職員体制の補助金というのは出てこないというふうに聞いています。同じようなことかなと思います。やはり現実問題として、こういう体制が取られていないというような問題が現場では起きているのではないかなというふうに思います。事業者がどう説明しているかはまた別問題として。\n登園自粛のときも、これ、保護者が申し出たときなのですけど、保護者が申し出たときも何かきちんと柔軟に対応がされているのでしょうか。具体的な例としては、園児のきょうだいにコロナ感染の疑いが出たとき、それで陽性になったら明らかに濃厚接触者だから多分対応が違うと思うのですけども、疑いが出たときの、まだきちんと結論が出る前に、品川区としては保育園に預かってほしいという要請が来ているというふうに聞いたのですけど、それ、間違いではないのでしょうか。\nそれで、例えばこの保護者が、やはりリスクがあるから休ませたいんですといったときの日割りの徴収などがあれば、保護者としても割と休ませやすいというようなことがあるのかなと思うのですけど、その辺についてどうなのでしょう。保護者がちょっと用心のため休ませたいというようなときも、もう濃厚接触者と認定されればまた別の扱いがあるのは承知しているのですけど、その間タイムラグがあるわけです。そのときに、保育園としてはリスクが高いわけだからあまり預かりたくないですよね。まだでも濃厚接触者と認定されていないから、基本は預からなければいけない。そこで感染が広がる可能性があるわけではないですか。そのときに保護者としては申し訳ないというのもあるでしょうし、休ませたいというときに、特に今、保育料を払わなければいけない、０、１、２歳は結構保育料高いですよね。だから、保護者の判断になりますけど、例えばそういうようなこともあっていいのではないかなということだと思うのですけど、その辺についていかがでしょうか。"},{"i":237,"speaker":"立木保育課長","text":"保育料の日割りの件ですので、私のほうからお答えさせていただきます。\n今おっしゃられたケースというのは確かに存在することかなと思っております。ただ、今は厚生労働省のほうも、保育料の取扱い等いろいろ見ている中では、区からの登園自粛のお願い、こちらをした場合にのみ、保育料の部分に関しては日割りが認められている形になっておりますので、そのきょうだい関係で感染防止という観点からというところに関しましては、今後の課題なのかなというふうに考えてございます。今の状況では、日割りのほうはできないという形になってございます。"},{"i":238,"speaker":"吉田委員","text":"分かりました。だから現状はなかなか、今ようやく想定ができるようになったというようなこともあると思いますので、それこそ感染者の発生が落ち着いている今、ぜひ前向きに検討を進めていただきたいというふうに思います。\nそれから、さっきの副反応のとき、これについてはぜひ実態を調べて、現実にお金も大事ですけど、そこに職員が別の人が配置されないと、結局ほかの人たちの負担が増える。では自分が出ようかというように、責任感が皆さん強いのでそうなってしまう可能性があると思いますので、ぜひそれも前向きに進めていただきたいです。\nそれから、項目の２番について、私、この２番の項目については、あれ、補正予算がついているのだけど足りないのかなと思って、陳情者の方に伺いました。そうしたらやはり、これ、費用を補助してくださいという、費用の補助がやはり、補正予算のときは物品で来るではないですか。やはり、園によって必要なものというのは違ってくるし、補正予算でついたものでは足りなくて買い足したところでまた新たな補正予算がついて同じものが来てしまったとかいうこともあるやに聞いています。そういう補正予算もというか、当然税金ですので、やはり園にとって必要な形での費用の補助とか、または必要な物を聞き取った上でのことになるといいかなというふうに思います。\nこれ、１番に関して言うと、私たち今までは補正予算のときも、ＰＣＲ検査の対象者が増えていくときも、保育園については、子どもたちの重症化リスクが低いからという理由でずっと後回しにされてきた経緯があります。ここの陳情文に書いてありますけど、子どもたちは重症化リスクが低いかもしれないけど、そこにほかの医療関係者とかが子どもを預けてそれぞれ大変な仕事をしているわけです。その人たちの働いている先の重症化率はとても高いわけです。\n子どもたちの重症化リスクが低いからというストレートな理由で、保育施設関係者へのＰＣＲ検査がなかなか広がらないということについては、ちょっと考えが浅いのではないかということを意見申し上げてきました。それで、今日は文教委員会に直接ですので、ぜひやはり、この千葉県の例も書いてありますけれど、医療関係者とか、それから保健所関係者とか、介護従事者も当然多いですが、保育園に預けてたくさん働いている方たちいらっしゃるのでぜひ、そういうこともありますので、ＰＣＲ検査の定義というのは私も専門性全然ないので分かりませんけど、ぜひＰＣＲ検査の対象は広げていただきたいなというふうに思います。\nここに書いてありますけど、感染者の発生が落ち着いている今だから、やはりもう１回改めて、保育所がいろいろなエッセンシャルワーカーの中でもいろいろなエッセンシャルワークに関連している職業だということを理解していただいて、ぜひ要望を受け入れていただきたいなというふうに思います。費用の補助の考え方とか、ＰＣＲ検査の対象の広げ方とか、何かお考えあれば伺いたいです。"},{"i":239,"speaker":"若生保育支援課長","text":"陳情の２番のところでの、費用補助というところでございますが、区のほうでは、特に私立園中心ですけれども、物品等の購入費用の補助という形での、いわゆる園のほうで必要な物品ですとか感染防止の対策、こういったものにかかった費用に対して充てられる形で補助事業を昨年度から今年度も引き続き実施してございます。\nそれと別に昨年度は、物品のほうでも、ある程度こちらのほうで必要だろうと思われるものについては区で購入して、一斉に配付したというところもございますが、基本的には、特に私立園に関しましては、各園それぞれの状況ですとかも異なる部分ございますので、そういった必要な物品に関して充てられるように、補助金としてお金で支給していくというようなところを中心としてやっているところでございます。"},{"i":240,"speaker":"吉田委員","text":"ＰＣＲ検査の対象の広げ方についても伺ったのですけど、やはり保育という仕事がいろいろなほかの仕事に全部つながってくるわけです。そういう役割だということをぜひ認識して、今後ＰＣＲ検査の対象の検討をしていただきたいのですが、その辺についていかがでしょうか。"},{"i":241,"speaker":"初貝保育教育運営担当課長","text":"今、委員にご指摘いただいたＰＣＲ検査の対象に関しましては、先ほども答弁させていただきましたけれども、現在は、園で陽性者が出た場合、濃厚接触者を保健所等々で確認をして特定をして、というようなところで対応しているところでございます。\n今後に関しましては、区としてのＰＣＲ検査の考え方等を検討しまして、方向性だったり、保育所でのＰＣＲ検査の在り方など考えていきたいと考えております。"},{"i":242,"speaker":"吉田委員","text":"ぜひ、それぞれ検討していただきたいというふうに思います。\n先ほどの質疑の中でありましたけど、保育という事業の性質がどうしても感染防止がしにくい事業です。先ほどのご答弁では、子どもたちがなかなかマスクするのは難しいという、そちらのほうでしたけれども、保育士も、何か報道されていましたよね、保育士がマスクしていると子どもたちの表情が消えていくと。まだ言葉が不十分ですから、やはり表情でお互いコミュニケーションを取っている。そういう中で、保育士もやはり、保育の質ということを考えたらマスクはしにくいという、そういう事業です。\nそこで、防ぐには、ワクチンの優先接種もありますし、ワクチンができない人にとってはＰＣＲ検査の定期的な実施というのが、子どもたちへの感染も防ぐことになると同時に、やはりそこの保育園に子どもを預けている、いろいろな仕事を持った方たちが安心して働くことにもつながりますので、ぜひこれについては、よく検討していただきたいと思います。これは要望です。"},{"i":243,"speaker":"あくつ委員長","text":"ほかによろしいでしょうか。\nほかにご発言がないようですので、これで質疑を終了いたします。\nそれではまず、令和３年陳情第５３号の取扱いについてご意見を伺いたいと思います。\n継続にする、あるいは結論を出す、どちらかご発言願います。また、結論を出すのであれば、その結論についてもご発言ください。\nそれでは、品川区議会自民党からお願いいたします。"},{"i":244,"speaker":"松澤委員","text":"本日結論を出すでお願いいたします。不採択でお願いいたします。\n理由は、いろいろご答弁をお聞きしておりましたけれども、品川区は現状、第６波に向けても引き続き努力していただいていると思います。しかしながら、感染者の増加というものの拡大があると思いますので、引き続き気を引き締めて継続して、頑張っていただきたいと思います。"},{"i":245,"speaker":"つる委員","text":"本日結論を出すで、態度は不採択です。\n冒頭のご説明の中で、ここに列挙されている６項目についても、品川区の現状の対応が取られているということと、１番については、その保健所として示されていないという観点も含めて、確認ができました。また、今あったように、全体としてこのコロナ対策というのは、保育現場に限らず、区民一人一人の生活も含めてしっかりと対策、対応をしていかなければいけないと、これは国と自治体挙げてしっかりと対応していかないといけないところですので、それは引き続きしっかりとやっていただきたいというふうに思います。"},{"i":246,"speaker":"安藤委員","text":"本日結論を出すで、採択を主張しますけど、やはり感染拡大を防ぐためと、あと、万が一感染された際にも保護者の負担軽減と感染被害を防ぐため、どれも必要な対策なのではないかと。特に一定、新規感染者が落ち着いている今だからこそ、やはり検査体制というのは整えないと、本当にまた再拡大になりますよ、ということでやるべきだと思います。\nそれと、質疑を聞いていてやはり思ったのは、子どもが一番コロナで大変なつらい思いをしていると思うのです。やはり、先ほどのマスクをつけた保育の質疑などもありましたけど、そういうときに保育園とか学校というのは、そういった本当に大事な時期にこういう我慢あるいはリスクにさらされながらつらい思いをしているというところには心を寄せて、できる対策というのは本当に取っていただきたいですし、そういう区政にさせていくためにも、私はこれはやはりしっかり採択をして、対策を進めていくべきだと思います。"},{"i":247,"speaker":"吉田委員","text":"本日結論を出すで、採択でお願いします。\n繰り返しになりますので簡単に言いますけれども、やはり保育という事業が様々な事業に直接つながっていく事業だということを改めて認識していただいて、ぜひこの項目、それぞれなさっていると思いますけれど、一歩踏み込んで、対策を今だからこそ強めていただきたいと思いまして、採択を主張いたします。"},{"i":248,"speaker":"松本委員","text":"本日結論を出すで、不採択でお願いします。\n理由といたしましては、まず１番、例えばＰＣＲ検査ですけれども、安心という言葉がたくさん出てくるのですけれども、ただ一方で、請願で、学校についても以前出てきたところがありますけれども、そこでも、体制の整備等というところとの兼ね合いで、では本当にこれは効果的なのか、安全ではなくて安心を求めるということであれば、無限に対象は広がっていくというふうに思います。\n例えば世田谷区の世田谷モデルというところ、当初は大きくぶち上げたものの、二転三転というふうなところで報じられているところでもある。そういう中で、私はこのＰＣＲ検査を定期的にやることが効果的なのかというところは、現状ではそこまでの科学的に立証されているところではないというふうには思っています。\nまた、あと、２番のところですけれども、私も、先ほど、この補助金の交付要綱を確認したところ、発注書とか請求書とか、そういったものをしっかりとやれば交付されるということで、我々がこれ採択というふうに言ったら、ここの部分が間違いになってしまうおそれもありますので、そういったところも含めて不採択というふうに申し上げさせていただきます。"},{"i":249,"speaker":"あくつ委員長","text":"それでは、本陳情につきましては、結論を出すとのご意見でまとまったようでございますので、そのような取扱いでよろしいでしょうか。\n〔「異議なし」と呼ぶ者あり〕"},{"i":250,"speaker":"あくつ委員長","text":"それでは、本件は結論を出すことに決定いたしました。\n先ほど、それぞれの方のご意見を伺いましたので、本陳情につきましては、挙手により採決を行います。\nそれでは、令和３年陳情第５３号、新型コロナウイルス感染症に関する要望についての陳情を採決いたします。\n本件を採択とすることに賛成の方は挙手願います。\n〔賛成者挙手〕"},{"i":251,"speaker":"あくつ委員長","text":"賛成者少数でございます。よって、本件は不採択と決定いたしました。\n以上で本件および請願・陳情審査を終了いたします。\n────────────────────────────────────────────\n３ 報告事項\n専決処分の報告について（報告第２０号）"},{"i":252,"speaker":"あくつ委員長","text":"次に、予定表３の報告事項を聴取いたします。\n専決処分の報告について（報告第２０号）を議題に供します。\n本件につきまして、理事者よりご説明願います。"},{"i":253,"speaker":"立木保育課長","text":"私からは、報告第２０号の専決処分について報告をさせていただきます。\n本件は、地方自治法第１８０条第１項の規定による議会の指定議決に基づき、公務において自転車走行中に起きた、自転車との接触事故の和解および損害賠償額の決定について、令和３年１１月１日に専決処分いたしましたので、同条第２項の規定に基づき報告するものでございます。\n事故の概要でございますが、令和３年８月３日、保育園の職員が運転する自転車が、品川区豊町２丁目２３番先の交差点に進入する際、安全運転を怠り、右側から直進してきた自転車に接触したため、同車の運転手が腹部を打撲し、同車のフレーム等を破損したものでございます。\n損害賠償額および事故の相手方につきましては、報告書面に記載のとおりでございます。\n職員による自転車の運転につきましては、日頃から注意を促しているところでございますが、さらに安全運転の徹底を図り、再発防止に努めてまいります。\n申し訳ございませんでした。"},{"i":254,"speaker":"あくつ委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑等がございましたらご発言願います。"},{"i":255,"speaker":"安藤委員","text":"これ、どんな業務中の自転車走行事故だったのかというのが知りたいです。\nあとは、こういった損害賠償金というのは自転車保険とかからは出ないものなのでしょうか。\nその２点、お伺いします。"},{"i":256,"speaker":"立木保育課長","text":"これは園の職員が保育課のほうに出張をした帰り、園に戻る途中の事故でございます。\nそれから、こちら損害賠償のほうでございますが、区が加入しております自治体賠償保険のほうから、損害賠償金として支払われたものでございます。"},{"i":257,"speaker":"あくつ委員長","text":"ほかにございますか。\nほかにご発言がないようですので、以上で報告事項を終了いたします。\n────────────────────────────────────────────\n４ その他"},{"i":258,"speaker":"あくつ委員長","text":"最後に予定表４のその他を議題に供します。\nその他で何かございますか。\nないようですので、以上でその他を終了いたします。\n以上で本日の予定は全て終了いたしました。\n明日も午前１０時からの開会となりますので、よろしくお願いいたします。\nこれをもちまして、文教委員会を閉会いたします。\n○午後 ２時５９分閉会"}]});
